/**
 * The "Triggers" tab: the list of content-warning themes that authors tag stories with and judges block. The rules
 * (docs/story-review-next.md §1) live in the database; this screen only offers what it allows:
 *   - Add: the slug is made from the label and never changes.
 *   - Edit the label, description and place in the list. While a round is grouping, assigning or reviewing, a warning
 *     says that judges chose their blocklists from the current wording: edit for clarity, not meaning.
 *   - Retire / Reactivate: a retired theme cannot be picked any more but stays on everything that has it and still
 *     counts for matching.
 *   - Delete: only shown when nothing uses the theme (otherwise Retire is the way).
 * Every change is logged; the newest are listed at the bottom.
 */
import { addTrigger, adminTriggers, deleteTrigger, setTriggerActive, triggerChanges, updateTrigger } from '../api';
import type { AdminTrigger, TriggerChange } from '../types';
import { esc, fmtDateTime, type AdminContext, type AdminTab } from './context';

/** Rounds in these states have judges whose blocklists were chosen from the current wording. */
const WORDING_LOCKED = ['grouping', 'assigning', 'reviewing'];

const FIELD_NAMES: Record<TriggerChange['field'], string> = {
  created: 'added', label: 'label', description: 'description', position: 'place in the list', active: 'active', deleted: 'deleted',
};

export class TriggersTab implements AdminTab {
  id = 'triggers';
  label = 'Triggers';

  private list: AdminTrigger[] = [];
  private changes: TriggerChange[] = [];
  /** The slug being edited, if any. */
  private editing: string | null = null;

  async load(ctx: AdminContext) {
    [this.list, this.changes] = await Promise.all([adminTriggers(ctx.event?.id ?? null), triggerChanges(30)]);
    if (this.editing && !this.list.some((t) => t.slug === this.editing)) this.editing = null;
  }

  render(ctx: AdminContext): string {
    const running = ctx.round && WORDING_LOCKED.includes(ctx.round.status);
    const draft = ctx.draftTrigger;
    return `
      <p class="muted">These are the content-warning themes. Authors tag their stories with them and judges block the ones they do not want to read. A theme's short name (its slug) is fixed when it is added and never changes.</p>
      ${running ? `<div class="alert alert-warning"><b>Round ${esc(ctx.round!.number)} is ${esc(ctx.round!.status)}.</b> Judges chose their blocklists from the current wording, so edit a label or description to make it clearer, not to change what it means. A new meaning is a new theme.</div>` : ''}
      <div class="section">
        <h3>Add a theme</h3>
        ${draft ? '<div class="alert alert-info">Filled in from a judge\'s report. Change the wording as you like, then add it. It does not tag the story: do that by hand.</div>' : ''}
        <div class="form-grid">
          <div class="field"><label for="tg-label">Label (what people see)</label><input id="tg-label" maxlength="80" value="${esc(draft?.label ?? '')}" placeholder="e.g. Medical procedures" /></div>
          <div class="field"><label for="tg-desc">Description (optional)</label><input id="tg-desc" maxlength="300" value="${esc(draft?.description ?? '')}" placeholder="One line that tells a reader what it covers" /></div>
        </div>
        <div class="row" style="margin-top: 0.75rem;">
          <button type="button" class="btn btn-primary" data-action="add-trigger" ${ctx.busy ? 'disabled' : ''}>Add the theme</button>
          ${draft ? '<button type="button" class="btn btn-secondary" data-action="clear-draft">Clear</button>' : ''}
        </div>
      </div>
      <div class="section">
        <h3>The list (${this.list.length})</h3>
        ${this.list.length ? this.table(ctx, Boolean(running)) : '<div class="empty">No themes yet.</div>'}
        <p class="muted" style="margin-bottom:0;">Counts: stories include drafts and withdrawn ones. "Judges" are the registered judges of ${esc(ctx.event?.title ?? 'the event')} who block the theme.</p>
      </div>
      <div class="section">
        <h3>Recent changes</h3>
        ${this.changes.length ? `<div class="table-wrap"><table><thead><tr><th>When</th><th>Who</th><th>Theme</th><th>What</th><th>From</th><th>To</th></tr></thead><tbody>
          ${this.changes.map((c) => `<tr><td>${esc(fmtDateTime(c.changed_at))}</td><td>${esc(c.changed_by_name ?? '')}</td><td>${esc(c.slug)}</td><td>${esc(FIELD_NAMES[c.field] ?? c.field)}</td><td>${esc(c.old_value ?? '')}</td><td>${esc(c.new_value ?? '')}</td></tr>`).join('')}
        </tbody></table></div>` : '<div class="empty">Nothing has been changed yet.</div>'}
      </div>`;
  }

  private table(ctx: AdminContext, running: boolean): string {
    const last = this.list.length - 1;
    return `<div class="table-wrap"><table><thead><tr><th>Order</th><th>Theme</th><th class="num">Stories here</th><th class="num">Stories, all events</th><th class="num">Judges</th><th></th></tr></thead><tbody>
      ${this.list.map((t, i) => (this.editing === t.slug ? this.editRow(t, ctx, running) : `<tr>
        <td style="white-space:nowrap;"><button type="button" class="btn btn-secondary btn-sm" data-action="move-up" data-slug="${esc(t.slug)}" data-index="${i}" aria-label="Move ${esc(t.label)} up" ${ctx.busy || i === 0 ? 'disabled' : ''}>↑</button>
          <button type="button" class="btn btn-secondary btn-sm" data-action="move-down" data-slug="${esc(t.slug)}" data-index="${i}" aria-label="Move ${esc(t.label)} down" ${ctx.busy || i === last ? 'disabled' : ''}>↓</button></td>
        <td><b>${esc(t.label)}</b> ${t.active ? '' : '<span class="badge badge-warning">retired</span>'}
          ${t.description ? `<div class="muted">${esc(t.description)}</div>` : ''}<div class="muted">${esc(t.slug)}</div></td>
        <td class="num">${t.stories_in_event}</td><td class="num">${t.stories_total}</td>
        <td class="num" title="${esc(`${t.default_blockers} people have it in their default blocklist`)}">${t.judges_blocking}</td>
        <td><div class="row">
          <button type="button" class="btn btn-secondary btn-sm" data-action="edit-trigger" data-slug="${esc(t.slug)}" ${ctx.busy ? 'disabled' : ''}>Edit</button>
          ${t.active
            ? `<button type="button" class="btn btn-secondary btn-sm" data-action="retire-trigger" data-slug="${esc(t.slug)}" title="Authors and judges can no longer pick it; it stays where it is and still counts for matching" ${ctx.busy ? 'disabled' : ''}>Retire</button>`
            : `<button type="button" class="btn btn-secondary btn-sm" data-action="reactivate-trigger" data-slug="${esc(t.slug)}" ${ctx.busy ? 'disabled' : ''}>Reactivate</button>`}
          ${t.deletable ? `<button type="button" class="btn btn-danger btn-sm" data-action="delete-trigger" data-slug="${esc(t.slug)}" data-label="${esc(t.label)}" ${ctx.busy ? 'disabled' : ''}>Delete</button>` : ''}
        </div></td></tr>`)).join('')}
      </tbody></table></div>`;
  }

  private editRow(t: AdminTrigger, ctx: AdminContext, running: boolean): string {
    return `<tr><td></td><td colspan="4">
        <div class="form-grid">
          <div class="field"><label for="tg-edit-label">Label</label><input id="tg-edit-label" maxlength="80" value="${esc(t.label)}" /></div>
          <div class="field"><label for="tg-edit-desc">Description</label><input id="tg-edit-desc" maxlength="300" value="${esc(t.description ?? '')}" /></div>
        </div>
        <div class="muted" style="margin-top: 0.4rem;">${running ? 'A round is running: judges chose from the current wording, so change it for clarity, not meaning. ' : ''}The short name <b>${esc(t.slug)}</b> stays.</div>
      </td><td><div class="row">
        <button type="button" class="btn btn-primary btn-sm" data-action="save-trigger" data-slug="${esc(t.slug)}" ${ctx.busy ? 'disabled' : ''}>Save</button>
        <button type="button" class="btn btn-secondary btn-sm" data-action="cancel-edit">Cancel</button>
      </div></td></tr>`;
  }

  async onAction(name: string, el: HTMLElement, ctx: AdminContext, root: ParentNode) {
    const slug = el.getAttribute('data-slug') ?? '';
    const input = (id: string) => root.querySelector<HTMLInputElement>(`#${id}`)?.value ?? '';
    switch (name) {
      case 'add-trigger': {
        const label = input('tg-label').trim();
        if (!label) return ctx.flash('error', 'Type a label first.');
        return ctx.run(async () => {
          await addTrigger(label, input('tg-desc').trim() || null);
          ctx.draftTrigger = null;
          return `“${label}” is added (active, last in the list).`; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        });
      }
      case 'clear-draft':
        ctx.draftTrigger = null;
        return ctx.rerender();
      case 'edit-trigger':
        this.editing = slug;
        return ctx.rerender();
      case 'cancel-edit':
        this.editing = null;
        return ctx.rerender();
      case 'save-trigger': {
        const label = input('tg-edit-label').trim();
        if (!label) return ctx.flash('error', 'The label cannot be empty.');
        return ctx.run(async () => {
          await updateTrigger(slug, { label, description: input('tg-edit-desc').trim() });
          this.editing = null;
          return 'Saved.';
        });
      }
      case 'move-up':
      case 'move-down': {
        // places are 1-based and the row's index is 0-based: one place up is `index`, one place down is `index + 2`
        const place = Number(el.getAttribute('data-index')) + (name === 'move-up' ? 0 : 2);
        return ctx.run(async () => {
          await updateTrigger(slug, { position: place });
        });
      }
      case 'retire-trigger':
        if (!confirm('Retire this theme? Authors and judges can no longer pick it. Stories and blocklists that already have it keep it, and it still counts when judges are matched to stories.')) return; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        return ctx.run(async () => {
          await setTriggerActive(slug, false);
          return 'Retired.';
        });
      case 'reactivate-trigger':
        return ctx.run(async () => {
          await setTriggerActive(slug, true);
          return 'Active again.';
        });
      case 'delete-trigger':
        if (!confirm(`Delete “${el.getAttribute('data-label') ?? slug}”? Nothing uses it. This cannot be undone (the change log keeps a record).`)) return; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        return ctx.run(async () => {
          await deleteTrigger(slug);
          return 'Deleted.';
        });
    }
  }
}
