export class RgaiSubmitElement extends BaseElement {
  private stories: Story[] = [];
  private openEvents: EventItem[] = [];
  private selectedEventId = '';
  private triggers: TriggerItem[] = [];

  // View state
  private mode: 'list' | 'editor' = 'list';
  private editorTab: 'write' | 'preview' = 'write';
  private editingStory: Partial<Story> | null = null;
  private loading = true;
  private saving = false;
  private statusMessage: { text: string; type: 'success' | 'error' | 'warning' } | null = null;

  constructor() {
    super(styles);
  }

  private get selectedEvent(): EventItem | undefined {
    return this.openEvents.find((e) => e.id === this.selectedEventId);
  }

  /** Submissions are closed when the admin closed them or the deadline passed (the database enforces the same). */
  private get submissionsClosed(): boolean {
    const ev = this.selectedEvent;
    if (!ev) return true;
    return Boolean(ev.submissions_closed) || (Boolean(ev.submissions_close_at) && Date.parse(ev.submissions_close_at as string) <= Date.now());
  }

  private closedBanner(): string {
    const ev = this.selectedEvent;
    if (!ev) return `<div class="alert alert-warning">There is no event open for submissions right now.</div>`;
    if (this.submissionsClosed) {
      return `<div class="alert alert-warning">🔒 Submissions for “${escapeHtml(ev.title)}” are closed. Your stories are read-only. If you need to withdraw one, please contact the organizers.</div>`;
    }
    if (ev.submissions_close_at) {
      const when = new Date(ev.submissions_close_at).toLocaleString(undefined, { dateStyle: 'long', timeStyle: 'short' });
      return `<div class="alert alert-success">Submissions are open until ${escapeHtml(when)}. Stories lock when submissions close.</div>`;
    }
    return '';
  }

  async connectedCallback() {
    await this.loadInitialData();
  }

  private async loadInitialData() {
    this.loading = true;
    this.render();

    try {
      const supabase = getSupabaseClient();
      const { data: authData } = await supabase.auth.getUser();

      // 1. Fetch active events
      const { data: events } = await supabase
        .from('events')
        .select('*')
        .eq('status', 'open')
        .order('created_at', { ascending: false });

      this.openEvents = events ?? [];
      this.selectedEventId = this.openEvents[0]?.id ?? '';

      // 2. Fetch the triggers (the form hides the retired ones a story does not already carry)
      const { data: trigData } = await supabase
        .from('triggers')
        .select('*')
        .order('position')
        .order('label');

      this.triggers = trigData ?? [];

      // 3. Fetch author stories
      if (authData?.user) {
        const { data: myStories } = await supabase
          .from('stories')
          .select('*')
          .eq('author_id', authData.user.id)
          .order('updated_at', { ascending: false });

        this.stories = myStories ?? [];
      }
    } catch (err) {
      console.warn('Error loading the submission portal:', err);
      this.statusMessage = { text: friendlyError(err, 'The submission portal could not be loaded.'), type: 'error' };
    } finally {
      this.loading = false;
      this.render();
    }
  }

  private render() {
    if (this.loading) {
      this.root.innerHTML = `
        <div class="submit-card">
          <p style="text-align:center; color:#64748b;">Loading story submission portal...</p>
        </div>
      `;
      return;
    }

    if (this.mode === 'editor') {
      this.renderEditor();
    } else {
      this.renderList();
    }
  }

  // ── Render Story List ──────────────────────────────────────────────────────
  private renderList() {
    this.root.innerHTML = `
      <div class="submit-card">
        <div class="header">
          <div class="title-group">
            <h2 class="title">My Stories</h2>
            <p class="subtitle">Draft, preview, and submit stories for blind peer review</p>
          </div>
          <div style="display:flex; gap:0.5rem; align-items:center;">
            ${this.submissionsClosed ? '' : `<button type="button" class="btn btn-primary" id="btn-create-story">
              + Write a New Story
            </button>`}
          </div>
        </div>

        ${
          this.statusMessage
            ? `<div class="alert alert-${this.statusMessage.type}">${escapeHtml(this.statusMessage.text)}</div>`
            : ''
        }
        ${this.closedBanner()}

        <!-- Event selector -->
        <div class="form-group" style="max-width: 380px;">
          <label for="event-select">Submitting to Event:</label>
          <select id="event-select">
            ${this.openEvents
              .map(
                (ev) => `
              <option value="${ev.id}" ${ev.id === this.selectedEventId ? 'selected' : ''}>
                ${escapeHtml(ev.title)}
              </option>
            `
              )
              .join('')}
          </select>
        </div>

        <!-- Story List -->
        ${
          this.stories.length === 0
            ? `
            <div class="empty-state">
              <div class="empty-icon">✍️</div>
              <p>You haven't drafted any stories for this event yet.</p>
              ${this.submissionsClosed ? '' : `<button type="button" class="btn btn-primary" id="btn-empty-create" style="margin-top: 0.5rem;">
                Write Your First Story
              </button>`}
            </div>
          `
            : `
            <div class="story-list">
              ${this.stories
                .map((story) => {
                  const statusBadgeClass =
                    story.locked
                      ? 'badge-locked'
                      : story.status === 'submitted'
                      ? 'badge-submitted'
                      : story.status === 'withdrawn'
                      ? 'badge-withdrawn'
                      : 'badge-draft';

                  const statusText =
                    story.locked
                      ? '🔒 Locked · In Review'
                      : story.status === 'submitted'
                      ? 'Submitted'
                      : story.status === 'withdrawn'
                      ? 'Withdrawn'
                      : 'Draft';

                  return `
                  <div class="story-item" data-id="${story.id}">
                    <div class="story-header">
                      <div>
                        <h3 class="story-title">${escapeHtml(story.title)}</h3>
                        <span class="badge ${statusBadgeClass}" style="margin-top: 0.35rem;">${statusText}</span>
                      </div>
                      <span class="word-count">
                        ${story.content.trim().split(/\\s+/).filter(Boolean).length} words
                      </span>
                    </div>

                    <p class="story-summary">${escapeHtml(story.summary)}</p>

                    <div class="tag-list">
                      ${
                        story.trigger_slugs.length > 0
                          ? story.trigger_slugs
                              .map((slug) => {
                                const tr = this.triggers.find((t) => t.slug === slug);
                                return `<span class="tag">⚠️ ${escapeHtml(tr ? tr.label : slug)}</span>`;
                              })
                              .join('')
                          : '<span class="tag" style="color:#059669;">No content warnings</span>'
                      }
                    </div>

                    <div class="story-actions">
                      ${
                        this.submissionsClosed
                          ? `<button type="button" class="btn btn-secondary btn-view" data-id="${story.id}">View Story</button>`
                          : !story.locked && story.status === 'draft'
                          ? `
                          <button type="button" class="btn btn-secondary btn-edit" data-id="${story.id}">Edit</button>
                          <button type="button" class="btn btn-success btn-quick-submit" data-id="${story.id}">Submit for Review</button>
                          <button type="button" class="btn btn-danger btn-delete" data-id="${story.id}">Delete</button>
                        `
                          : !story.locked && story.status === 'submitted'
                          ? `
                          <button type="button" class="btn btn-secondary btn-edit" data-id="${story.id}">Edit</button>
                          <button type="button" class="btn btn-danger btn-withdraw" data-id="${story.id}">Withdraw</button>
                        `
                          : `
                          <button type="button" class="btn btn-secondary btn-view" data-id="${story.id}">View Story</button>
                        `
                      }
                    </div>
                  </div>
                `;
                })
                .join('')}
            </div>
          `
        }
      </div>
    `;

    this.bindListEvents();
  }

  // ── Render Story Editor ────────────────────────────────────────────────────
  private renderEditor() {
    const isEditing = Boolean(this.editingStory?.id);
    const isLocked = Boolean(this.editingStory?.locked) || this.submissionsClosed;
    const title = this.editingStory?.title || '';
    const summary = this.editingStory?.summary || '';
    const content = this.editingStory?.content || '';
    const selectedTriggers = new Set(this.editingStory?.trigger_slugs || []);

    const wordCount = content.trim().split(/\s+/).filter(Boolean).length;

    this.root.innerHTML = `
      <div class="submit-card">
        <div class="header">
          <div class="title-group">
            <h2 class="title">${isLocked ? 'View Story (Locked)' : isEditing ? 'Edit Story' : 'New Story'}</h2>
            <p class="subtitle">Stories lock when submissions close</p>
          </div>
          <button type="button" class="btn btn-secondary" id="btn-back">
            ← Back to Stories
          </button>
        </div>

        ${
          this.statusMessage
            ? `<div class="alert alert-${this.statusMessage.type}">${escapeHtml(this.statusMessage.text)}</div>`
            : ''
        }

        ${
          isLocked
            ? `<div class="alert alert-warning">🔒 This story is locked: submissions are closed. Edits are disabled.</div>`
            : ''
        }

        <form id="story-form">
          <div class="form-group">
            <label for="input-title">Story Title</label>
            <input
              type="text"
              id="input-title"
              required
              maxlength="150"
              placeholder="Give your story a title..."
              value="${escapeHtml(title)}"
              ${isLocked ? 'disabled' : ''}
            />
          </div>

          <div class="form-group">
            <label for="input-summary">Synopsis / Hook</label>
            <p class="help-text">A 1–2 sentence summary shown to peer reviewers before they accept the assignment.</p>
            <textarea
              id="input-summary"
              rows="3"
              required
              maxlength="400"
              placeholder="Brief summary of the story hook..."
              ${isLocked ? 'disabled' : ''}
            >${escapeHtml(summary)}</textarea>
          </div>

          <div class="form-group">
            <label>Content & Trigger Warnings</label>
            <p class="help-text">
              Select all themes present in your story. Reviewers who have added these to their blocklist will not be assigned your story.
            </p>
            <div class="trigger-grid">
              ${pickableTriggers(this.triggers, selectedTriggers)
                .map(
                  (tr) => `
                <label class="trigger-checkbox-label">
                  <input
                    type="checkbox"
                    name="trigger-tag"
                    value="${escapeHtml(tr.slug)}"
                    ${selectedTriggers.has(tr.slug) ? 'checked' : ''}
                    ${isLocked ? 'disabled' : ''}
                  />
                  <div>
                    <strong>${escapeHtml(triggerLabel(tr))}</strong>
                    ${tr.description ? `<div style="font-size:0.75rem; color:#64748b;">${escapeHtml(tr.description)}</div>` : ''}
                  </div>
                </label>
              `
                )
                .join('')}
            </div>
          </div>

          <div class="form-group">
            <div class="editor-toolbar">
              <div class="editor-tabs">
                <button type="button" class="editor-tab-btn ${this.editorTab === 'write' ? 'active' : ''}" id="tab-write">Write</button>
                <button type="button" class="editor-tab-btn ${this.editorTab === 'preview' ? 'active' : ''}" id="tab-preview">Preview</button>
              </div>
              <span class="word-count" id="editor-word-count">${wordCount} words</span>
            </div>

            <div id="editor-container">
              ${
                this.editorTab === 'write'
                  ? `
                  <textarea
                    id="input-content"
                    class="content-textarea"
                    rows="16"
                    placeholder="Write or paste your story here in Markdown..."
                    ${isLocked ? 'disabled' : ''}
                  >${escapeHtml(content)}</textarea>
                `
                  : `
                  <div class="markdown-preview" id="preview-box">
                    ${content ? renderMarkdown(content) : '<em style="color:#94a3b8;">Nothing to preview yet.</em>'}
                  </div>
                `
              }
            </div>
          </div>

          <div style="display:flex; justify-content:space-between; align-items:center; margin-top:1.5rem; padding-top:1rem; border-top:1px solid #e2e8f0;">
            <button type="button" class="btn btn-secondary" id="btn-cancel">Cancel</button>

            ${
              !isLocked
                ? `
                <div style="display:flex; gap:0.5rem;">
                  <button type="button" class="btn btn-secondary" id="btn-save-draft" ${this.saving ? 'disabled' : ''}>
                    ${this.saving ? 'Saving...' : 'Save Draft'}
                  </button>
                  <button type="button" class="btn btn-success" id="btn-submit-story" ${this.saving ? 'disabled' : ''}>
                    Submit for Review
                  </button>
                </div>
              `
                : ''
            }
          </div>
        </form>
      </div>
    `;

    this.bindEditorEvents();
  }

  // ── Event Bindings ─────────────────────────────────────────────────────────
  private bindListEvents() {
    this.$('#btn-create-story')?.addEventListener('click', () => this.openEditor(null));
    this.$('#btn-empty-create')?.addEventListener('click', () => this.openEditor(null));

    this.$('#event-select')?.addEventListener('change', (e) => {
      this.selectedEventId = (e.target as HTMLSelectElement).value;
      this.render();
    });

    this.$$('.btn-edit').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        const story = this.stories.find((s) => s.id === id);
        if (story) this.openEditor(story);
      });
    });

    this.$$('.btn-view').forEach((btn) => {
      btn.addEventListener('click', () => {
        const id = btn.getAttribute('data-id');
        const story = this.stories.find((s) => s.id === id);
        if (story) this.openEditor(story);
      });
    });

    this.$$('.btn-quick-submit').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const id = btn.getAttribute('data-id');
        if (id) await this.submitStoryDirect(id);
      });
    });

    this.$$('.btn-delete').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const id = btn.getAttribute('data-id');
        if (id && confirm('Are you sure you want to delete this draft?')) {
          await this.deleteStory(id);
        }
      });
    });

    this.$$('.btn-withdraw').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const id = btn.getAttribute('data-id');
        if (id && confirm('Withdraw this story from review consideration?')) {
          await this.withdrawStory(id);
        }
      });
    });
  }

  private bindEditorEvents() {
    this.$('#btn-back')?.addEventListener('click', () => this.closeEditor());
    this.$('#btn-cancel')?.addEventListener('click', () => this.closeEditor());

    const contentTextarea = this.$<HTMLTextAreaElement>('#input-content');
    contentTextarea?.addEventListener('input', () => {
      if (this.editingStory) {
        this.editingStory.content = contentTextarea.value;
      }
      const words = contentTextarea.value.trim().split(/\s+/).filter(Boolean).length;
      const countEl = this.$('#editor-word-count');
      if (countEl) countEl.textContent = `${words} words`;
    });

    this.$('#tab-write')?.addEventListener('click', () => {
      this.syncEditorState();
      this.editorTab = 'write';
      this.render();
    });

    this.$('#tab-preview')?.addEventListener('click', () => {
      this.syncEditorState();
      this.editorTab = 'preview';
      this.render();
    });

    this.$('#btn-save-draft')?.addEventListener('click', async () => {
      await this.saveStory(false);
    });

    this.$('#btn-submit-story')?.addEventListener('click', async () => {
      if (
        confirm(
          'Submit your story for peer review? You can still edit it until submissions close; then it locks.'
        )
      ) {
        await this.saveStory(true);
      }
    });
  }

  private syncEditorState() {
    const titleInput = this.$<HTMLInputElement>('#input-title');
    const summaryInput = this.$<HTMLTextAreaElement>('#input-summary');
    const contentInput = this.$<HTMLTextAreaElement>('#input-content');

    const selectedTags: string[] = [];
    this.$$<HTMLInputElement>('input[name="trigger-tag"]:checked').forEach((cb) => {
      selectedTags.push(cb.value);
    });

    if (!this.editingStory) this.editingStory = {};
    if (titleInput) this.editingStory.title = titleInput.value;
    if (summaryInput) this.editingStory.summary = summaryInput.value;
    if (contentInput) this.editingStory.content = contentInput.value;
    this.editingStory.trigger_slugs = selectedTags;
  }

  private openEditor(story: Story | null) {
    this.editingStory = story ? { ...story } : { event_id: this.selectedEventId, trigger_slugs: [] };
    this.editorTab = 'write';
    this.mode = 'editor';
    this.saving = false;
    this.statusMessage = null;
    this.render();
  }

  private closeEditor() {
    this.mode = 'list';
    this.editingStory = null;
    this.saving = false;
    this.render();
  }

  // ── Database / Persistence Operations ──────────────────────────────────────
  private async saveStory(andSubmit = false) {
    this.syncEditorState();
    const title = (this.editingStory?.title || '').trim();
    const summary = (this.editingStory?.summary || '').trim();
    const content = (this.editingStory?.content || '').trim();
    const triggers = this.editingStory?.trigger_slugs || [];

    if (!title || !summary || !content) {
      this.statusMessage = { text: 'Title, summary, and story content are all required.', type: 'error' };
      this.render();
      return;
    }

    this.saving = true;
    this.render();

    try {
      const supabase = getSupabaseClient();
      const { data: authData } = await supabase.auth.getUser();

      const storyPayload: Partial<Story> = {
        event_id: this.selectedEventId,
        title,
        summary,
        content,
        trigger_slugs: triggers,
        status: andSubmit ? 'submitted' : 'draft',
        submitted_at: andSubmit ? new Date().toISOString() : undefined,
        updated_at: new Date().toISOString(),
      };

      if (!authData?.user) throw new Error('Please sign in to save a story.');
      storyPayload.author_id = authData.user.id;
      if (this.editingStory?.id) {
        const { error } = await supabase.from('stories').update(storyPayload).eq('id', this.editingStory.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from('stories').insert(storyPayload);
        if (error) throw error;
      }

      this.statusMessage = {
        text: andSubmit ? 'Story submitted for review successfully!' : 'Draft saved successfully.',
        type: 'success',
      };
      this.closeEditor();
      await this.loadInitialData();
    } catch (err: unknown) {
      this.statusMessage = {
        text: friendlyError(err),
        type: 'error',
      };
      this.render();
    } finally {
      this.saving = false;
    }
  }

  private async submitStoryDirect(id: string) {
    try {
      const supabase = getSupabaseClient();
      const { data: authData } = await supabase.auth.getUser();

      if (!authData?.user) throw new Error('Please sign in to submit a story.');
      const { error } = await supabase
        .from('stories')
        .update({ status: 'submitted', submitted_at: new Date().toISOString() })
        .eq('id', id);
      if (error) throw error;
      this.statusMessage = { text: 'Story submitted for review!', type: 'success' };
      await this.loadInitialData();
    } catch (err: unknown) {
      this.statusMessage = { text: friendlyError(err), type: 'error' };
      this.render();
    }
  }

  private async deleteStory(id: string) {
    try {
      const supabase = getSupabaseClient();
      const { data: authData } = await supabase.auth.getUser();

      if (!authData?.user) throw new Error('Please sign in to delete a story.');
      const { error } = await supabase.from('stories').delete().eq('id', id);
      if (error) throw error;
      this.statusMessage = { text: 'Draft deleted.', type: 'warning' };
      await this.loadInitialData();
    } catch (err: unknown) {
      this.statusMessage = { text: friendlyError(err), type: 'error' };
      this.render();
    }
  }

  private async withdrawStory(id: string) {
    try {
      const supabase = getSupabaseClient();
      const { data: authData } = await supabase.auth.getUser();

      if (!authData?.user) throw new Error('Please sign in to withdraw a story.');
      const { error } = await supabase
        .from('stories')
        .update({ status: 'withdrawn' })
        .eq('id', id);
      if (error) throw error;
      this.statusMessage = { text: 'Story withdrawn from review.', type: 'warning' };
      await this.loadInitialData();
    } catch (err: unknown) {
      this.statusMessage = { text: friendlyError(err), type: 'error' };
      this.render();
    }
  }
}

if (!customElements.get('rgai-submit')) {
  customElements.define('rgai-submit', RgaiSubmitElement);
}
