/**
 * The "Judges" tab: choosing and inviting the people who judge a round. Round 1 fills itself (everyone who registers
 * is in); from round 2 on the organizers pick from the registered judges, with what each did before beside the name,
 * or look someone up by exact email, and invite them. An invited person is not seated until they accept in the app.
 */
import { addToBlocklist, adminUnregistrations, findUserByEmail, inviteJudges, judgeCandidates } from '../api';
import type { BlocklistResult, FoundUser, JudgeCandidate, Unregistration } from '../types';
import { esc, fmtDateTime, type AdminContext, type AdminTab } from './context';

type Filter = 'all' | 'not-invited' | 'invited' | 'accepted';

export class JudgesTab implements AdminTab {
  id = 'judges';
  label = 'Judges';

  private candidates: JudgeCandidate[] = [];
  /** Judges who unregistered from this event (a dated line each). */
  private unregistered: Unregistration[] = [];
  private selected = new Set<string>();
  private filter: Filter = 'all';
  private email = '';
  /** The result of the last lookup by email; `searched` is true once a lookup ran (so "not found" can be shown). */
  private found: FoundUser | null = null;
  private searched = false;
  /** The judge whose blocklist is being added to, the themes ticked so far, and (once the database asked) what to do about opened seats. */
  private blockFor: { judgeId: string; picked: Set<string>; ask: BlocklistResult | null } | null = null;

  async load(ctx: AdminContext) {
    this.candidates = ctx.round ? await judgeCandidates(ctx.round.id) : [];
    this.unregistered = ctx.event ? await adminUnregistrations(ctx.event.id) : [];
    // forget selections that are no longer possible (invited meanwhile, or another round)
    const open = new Set(this.candidates.filter((c) => !c.invitation).map((c) => c.user_id));
    for (const id of [...this.selected]) if (!open.has(id)) this.selected.delete(id);
  }

  render(ctx: AdminContext): string {
    const r = ctx.round;
    if (!r) return '<div class="empty">Create the round on the “Round setup” tab first.</div>';
    const invited = this.candidates.filter((c) => c.invitation === 'invited').length;
    const accepted = this.candidates.filter((c) => c.invitation === 'accepted').length;
    const closed = r.status === 'closed';
    const drafted = r.status !== 'planned';
    const intro = r.number === 1
      ? 'Round 1 fills itself: everyone who registers as a judge is in. You can still invite someone here, for instance a person who has not registered yet.'
      : 'Choose who judges this round. Each person gets an email and accepts in the app; until they do, they are not seated and do not count. The list shows what each did in the earlier rounds.';
    return `
      <div class="metrics">
        <div class="metric"><b>${this.candidates.length}</b><span>registered judges</span></div>
        <div class="metric"><b>${invited}</b><span>invited, not yet accepted</span></div>
        <div class="metric"><b class="${accepted ? 'good' : ''}">${accepted}</b><span>accepted</span></div>
        <div class="metric"><b>${this.unregistered.length}</b><span>unregistered</span></div>
      </div>
      <p class="muted">${esc(intro)}</p>
      ${closed ? '<div class="alert alert-info">This round is closed; nobody can be invited to it.</div>' : this.lookupSection(ctx)}
      ${this.blockPanel(ctx)}
      ${this.unregisteredSection()}
      <div class="section">
        <div class="row" style="justify-content: space-between; margin-bottom: 0.75rem;">
          <h3 style="margin:0;">Registered judges</h3>
          <div class="field"><label for="jd-filter" style="display:inline; margin-right: 0.4rem;">Show</label>
            <select id="jd-filter" data-action="filter" style="width:auto;">${([['all', 'everyone'], ['not-invited', 'not invited'], ['invited', 'invited'], ['accepted', 'accepted']] as const).map(([v, l]) => `<option value="${v}" ${this.filter === v ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
        </div>
        ${this.table(drafted, closed)}
        ${closed ? '' : this.inviteBar(ctx)}
      </div>`;
  }

  private lookupSection(ctx: AdminContext): string {
    const f = this.found;
    const known = f && this.candidates.find((c) => c.user_id === f.user_id);
    let result = '';
    if (this.searched && !f) result = '<p class="bad" style="margin-bottom:0;">Nobody has an account with that email.</p>';
    else if (f) {
      result = `<p style="margin-bottom:0;"><b>${esc(f.display_name)}</b> ${f.registered_as_judge ? '<span class="muted">is a registered judge</span>' : '<span class="muted">has an account but is not a registered judge yet; they will be registered with their default blocklist</span>'}
        ${known?.invitation ? `<span class="badge badge-info">${esc(known.invitation)}</span>` : `<button type="button" class="btn btn-primary btn-sm" data-action="invite-found" ${ctx.busy ? 'disabled' : ''}>Invite</button>`}</p>`;
    }
    return `
      <div class="section">
        <h3>Invite someone by email</h3>
        <div class="row">
          <div class="field" style="flex: 1; min-width: 240px;"><label for="jd-email">Their account email</label><input id="jd-email" type="email" autocomplete="off" maxlength="254" value="${esc(this.email)}" placeholder="name@example.org" /></div>
          <button type="button" class="btn btn-secondary" data-action="find-email" style="align-self:flex-end;" ${ctx.busy ? 'disabled' : ''}>Look up</button>
        </div>
        <div class="hint muted">The exact address only. The screen shows the name, never the address.</div>
        ${result ? `<div style="margin-top: 0.75rem;">${result}</div>` : ''}
      </div>`;
  }

  /** The judges who unregistered, newest first. Their numbers are never reused, so the gaps in the numbering are these. */
  private unregisteredSection(): string {
    if (!this.unregistered.length) return '';
    return `<details class="section"><summary style="cursor:pointer;"><b>${this.unregistered.length} ${this.unregistered.length === 1 ? 'judge has' : 'judges have'} unregistered</b> <span class="muted">(their numbers are not reused)</span></summary>
      <div class="table-wrap" style="margin-top:0.75rem;"><table><thead><tr><th>When</th><th>Judge</th><th class="num">#</th><th>Round 1 was</th><th class="num">Seats removed</th></tr></thead><tbody>
        ${this.unregistered.map((u) => `<tr><td>${esc(fmtDateTime(u.unregistered_at))}</td><td>${esc(u.display_name ?? '(account deleted)')}</td><td class="num">${esc(u.judge_number)}</td><td>${esc(u.round_status ?? 'not created yet')}</td><td class="num">${u.seats_removed}</td></tr>`).join('')}
      </tbody></table></div></details>`;
  }

  /** The "add to this judge's blocklist" panel: only ever adds; seats on groups that now conflict are released. */
  private blockPanel(ctx: AdminContext): string {
    const b = this.blockFor;
    const judge = b && this.candidates.find((c) => c.user_id === b.judgeId);
    if (!b || !judge) return '';
    const offered = ctx.triggers.filter((t) => t.active && !(judge.blocked_triggers ?? []).includes(t.slug));
    const names = (judge.blocked_triggers ?? []).map((s) => ctx.triggers.find((t) => t.slug === s)?.label ?? s);
    return `<div class="section">
      <h3>Add to the blocklist of ${esc(judge.display_name)}</h3>
      <p class="muted">Judges cannot change their blocklist while a round is running. A judge who asks can have themes <b>added</b> here; nothing is ever taken off. Their seats on groups that have an added theme are released (the stories go back to the pool), unless a story of the seat was already opened: then you choose.</p>
      <p>Blocks now: ${names.length ? esc(names.join(', ')) : '<i>nothing</i>'}</p>
      ${b.ask ? `<div class="alert alert-warning"><b>${esc(b.ask.seats_opened ?? 0)}</b> of the seats affected ${b.ask.seats_opened === 1 ? 'has' : 'have'} a story the judge already opened${b.ask.seats_unopened ? `; ${esc(b.ask.seats_unopened)} more ${b.ask.seats_unopened === 1 ? 'seat is' : 'seats are'} unopened and will be released either way` : ''}. Release the opened ${b.ask.seats_opened === 1 ? 'seat' : 'seats'} too (the opened story stays unreviewed by this judge), or keep ${b.ask.seats_opened === 1 ? 'it' : 'them'}?
        <div class="row" style="margin-top:0.6rem;"><button type="button" class="btn btn-danger btn-sm" data-action="block-confirm" data-choice="release" ${ctx.busy ? 'disabled' : ''}>Release the opened seats too</button>
          <button type="button" class="btn btn-secondary btn-sm" data-action="block-confirm" data-choice="keep" ${ctx.busy ? 'disabled' : ''}>Keep the opened seats</button></div></div>` : ''}
      <div class="row" style="margin-bottom: 0.75rem;">${offered.length ? offered.map((t) => `<label style="font-size:0.85rem;"><input type="checkbox" data-action="block-pick" data-slug="${esc(t.slug)}" ${b.picked.has(t.slug) ? 'checked' : ''} ${b.ask ? 'disabled' : ''} /> ${esc(t.label)}</label>`).join('') : '<span class="muted">They already block every active theme.</span>'}</div>
      <div class="row"><button type="button" class="btn btn-primary" data-action="block-add" ${ctx.busy || !b.picked.size || b.ask ? 'disabled' : ''}>Add ${b.picked.size || ''} to their blocklist</button>
        <button type="button" class="btn btn-secondary" data-action="block-cancel">Cancel</button></div>
    </div>`;
  }

  private async addBlocks(ctx: AdminContext, choice: 'ask' | 'release' | 'keep') {
    const b = this.blockFor;
    const eventId = ctx.event?.id;
    if (!b || !eventId) return;
    return ctx.run(async () => {
      const r = await addToBlocklist(eventId, b.judgeId, [...b.picked], choice);
      if (r.needs_choice) {
        b.ask = r;
        return;
      }
      this.blockFor = null;
      const released = r.seats_released ?? 0;
      const kept = r.seats_kept ?? 0;
      return `Added to the blocklist. ${released} ${released === 1 ? 'seat' : 'seats'} released${kept ? `, ${kept} kept (a story was already opened)` : ''}.`; // plain text (confirm box, flash or feedback message: escaped where it is shown)
    });
  }

  private visible(): JudgeCandidate[] {
    return this.candidates.filter((c) => this.filter === 'all' || (this.filter === 'not-invited' ? !c.invitation : c.invitation === this.filter));
  }

  private table(drafted: boolean, closed: boolean): string {
    const rows = this.visible();
    if (!this.candidates.length) return '<div class="empty">Nobody has registered as a judge yet.</div>';
    if (!rows.length) return '<div class="empty">Nobody matches this filter.</div>';
    return `<div class="table-wrap"><table><thead><tr><th></th><th class="num">#</th><th>Judge</th><th class="num">Reviews</th><th class="num">DNF</th><th class="num">Skipped</th><th class="num">Groups left</th><th class="num" title="Average length of the written comments">Comment</th><th class="num">Blocks</th><th class="num" title="How many of this round's drafted sets they could take">Sets</th><th>Status</th><th></th></tr></thead><tbody>
      ${rows.map((c) => `<tr>
        <td>${c.invitation || closed ? '' : `<input type="checkbox" data-action="toggle-judge" data-judge="${esc(c.user_id)}" aria-label="Select ${esc(c.display_name)}" ${this.selected.has(c.user_id) ? 'checked' : ''} />`}</td>
        <td class="num">${esc(c.judge_number)}</td><td>${esc(c.display_name)}</td>
        <td class="num">${c.earlier_reviews}</td><td class="num">${c.earlier_dnf}</td><td class="num">${c.earlier_skips}</td><td class="num">${c.earlier_groups_left}</td>
        <td class="num">${c.avg_comment_length || ''}</td><td class="num" title="${esc((c.blocked_triggers ?? []).join(', '))}">${c.blocked_count}</td>
        <td class="num ${drafted && c.eligible_sets === 0 ? 'bad' : ''}">${drafted ? c.eligible_sets : '–'}</td>
        <td>${c.invitation === 'accepted' ? '<span class="badge badge-success">accepted</span>' : c.invitation === 'invited' ? '<span class="badge badge-info">invited</span>' : ''}</td>
        <td><button type="button" class="btn btn-secondary btn-sm" data-action="block-more" data-judge="${esc(c.user_id)}" title="Add themes to this judge's blocklist, at their request">Block more</button></td></tr>`).join('')}
      </tbody></table></div>`;
  }

  private inviteBar(ctx: AdminContext): string {
    const open = this.visible().filter((c) => !c.invitation);
    return `<div class="row" style="margin-top: 1rem;">
      <button type="button" class="btn btn-primary" data-action="invite-selected" id="jd-invite" ${ctx.busy || !this.selected.size ? 'disabled' : ''}>${this.inviteLabel()}</button>
      <button type="button" class="btn btn-secondary btn-sm" data-action="select-visible" ${ctx.busy || !open.length ? 'disabled' : ''}>Select everyone shown who is not invited</button>
      <button type="button" class="btn btn-secondary btn-sm" data-action="clear-selection" ${ctx.busy || !this.selected.size ? 'disabled' : ''}>Clear</button>
    </div>`;
  }

  private inviteLabel(): string {
    const n = this.selected.size;
    return n ? `Invite ${n} selected` : 'Invite selected';
  }

  async onAction(name: string, el: HTMLElement, ctx: AdminContext, root: ParentNode) {
    const r = ctx.round;
    if (!r) return;
    switch (name) {
      case 'block-more':
        this.blockFor = { judgeId: el.getAttribute('data-judge') ?? '', picked: new Set(), ask: null };
        return ctx.rerender();
      case 'block-cancel':
        this.blockFor = null;
        return ctx.rerender();
      case 'block-pick': {
        const slug = el.getAttribute('data-slug') ?? '';
        if (!this.blockFor) return;
        if ((el as HTMLInputElement).checked) this.blockFor.picked.add(slug);
        else this.blockFor.picked.delete(slug);
        return ctx.rerender();
      }
      case 'block-add':
        return this.addBlocks(ctx, 'ask');
      case 'block-confirm':
        return this.addBlocks(ctx, el.getAttribute('data-choice') === 'release' ? 'release' : 'keep');
      case 'filter':
        this.filter = (el as HTMLSelectElement).value as Filter;
        return ctx.rerender();
      case 'toggle-judge': {
        const id = el.getAttribute('data-judge') ?? '';
        if ((el as HTMLInputElement).checked) this.selected.add(id);
        else this.selected.delete(id);
        // no full re-render: it would throw away what is typed in the email box
        const btn = root.querySelector<HTMLButtonElement>('#jd-invite');
        if (btn) {
          btn.textContent = this.inviteLabel();
          btn.disabled = !this.selected.size;
        }
        return;
      }
      case 'select-visible':
        for (const c of this.visible()) if (!c.invitation) this.selected.add(c.user_id);
        return ctx.rerender();
      case 'clear-selection':
        this.selected.clear();
        return ctx.rerender();
      case 'find-email': {
        const email = (root.querySelector<HTMLInputElement>('#jd-email')?.value ?? '').trim();
        this.email = email;
        if (!email) return ctx.flash('error', 'Type the email address of the person first.');
        this.found = null;
        this.searched = false;
        return ctx.run(async () => {
          this.found = await findUserByEmail(email);
          this.searched = true;
        });
      }
      case 'invite-found': {
        const f = this.found;
        if (!f) return;
        return ctx.run(async () => {
          await inviteJudges(r.id, [f.user_id]);
          this.found = null;
          this.searched = false;
          this.email = '';
          return `${f.display_name} is invited. They get an email with a link to accept.`; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        });
      }
      case 'invite-selected': {
        const ids = [...this.selected];
        if (!ids.length) return;
        if (!confirm(`Invite ${ids.length} ${ids.length === 1 ? 'person' : 'people'} to ${r.name}? Each gets an email with a link to accept.`)) return; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        return ctx.run(async () => {
          const res = await inviteJudges(r.id, ids);
          this.selected.clear();
          return `${res.invited} invited${res.already_in_round ? ` (${res.already_in_round} already were)` : ''}. The emails go out when you send the queued emails (Emails tab).`;
        });
      }
    }
  }
}
