/**
 * CSV for the admin exports. Titles, names and notes are user text that ends up in a spreadsheet, so a cell that a
 * spreadsheet would read as a formula (it starts with = + - @, a tab or a carriage return) gets a leading
 * apostrophe. Numbers and booleans are written as they are.
 */
import type { ExportRow, GroupResult, ReviewQuestion } from './types';

const FORMULA_START = /^[=+\-@\t\r]/;

export function csvCell(value: unknown): string {
  if (value === null || value === undefined) return '';
  let text: string;
  if (typeof value === 'number') text = Number.isFinite(value) ? String(value) : '';
  else if (typeof value === 'boolean') text = value ? 'yes' : 'no';
  else {
    text = Array.isArray(value) ? value.map((v) => String(v)).join('; ') : String(value);
    if (FORMULA_START.test(text)) text = `'${text}`;
  }
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

export function toCsv(rows: unknown[][]): string {
  return rows.map((r) => r.map(csvCell).join(',')).join('\r\n') + '\r\n';
}

/** One row per story review, last year's layout: who, what, the outcome, then one column per question. */
export function reviewsCsv(rows: ExportRow[], questions: ReviewQuestion[]): string {
  const qs = [...questions].filter((q) => !q.archived).sort((a, b) => a.position - b.position);
  const head = ['Group', 'Story', 'Judge number', 'Judge', 'Outcome', 'Submitted at', 'Skip reason', 'DNF reason', 'Note', ...qs.map((q) => q.label)];
  const body = rows.map((r) => [
    r.group_number, r.story_title, r.judge_number, r.judge_name, r.status, r.submitted_at, r.skip_reason, r.dnf_reason, r.note,
    ...qs.map((q) => r.answers?.[q.id] ?? ''),
  ]);
  return toCsv([head, ...body]);
}

/** One row per story with its rank, scores, counts and the group's close-call flags. */
export function groupResultsCsv(groups: GroupResult[]): string {
  const head = ['Group', 'Rank', 'Story', 'Centered score', 'Raw score', 'Scored reviews', 'Submitted', 'DNF', 'Skipped', 'Positive recommendations', 'Recommendations', 'Positive share', 'Advances', 'Group margin', 'Close call', 'Close-call reasons'];
  const body = groups.flatMap((g) =>
    g.stories.map((s) => [
      g.group_number, s.rank, s.title, s.weighted_score, s.raw_score, s.review_count, s.submitted_count, s.dnf_count, s.skip_count,
      s.positive_recommendations, s.recommendations, s.positive_share, s.advances, g.margin, g.close_call, g.close_call_reasons,
    ]),
  );
  return toCsv([head, ...body]);
}

/** Offers a CSV as a download (with a byte-order mark, so Excel reads UTF-8). */
export function downloadCsv(filename: string, csv: string): void {
  const url = URL.createObjectURL(new Blob(['﻿', csv], { type: 'text/csv;charset=utf-8' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
