/**
 * The review form's rules, in one place and free of the DOM, mirroring validate_review_answers() in the database
 * (which stays the backstop): every required question answered; a scale answer a number within the question's
 * range (default 0-10); a choice among the configured options; text not blank.
 */
import type { ReviewQuestion } from './types';

export type Answers = Record<string, unknown>;

export function scaleRange(q: ReviewQuestion): { min: number; max: number; minLabel: string; maxLabel: string } {
  const c = q.config as { min?: number; max?: number; min_label?: string; max_label?: string };
  return { min: Number.isFinite(c?.min) ? (c.min as number) : 0, max: Number.isFinite(c?.max) ? (c.max as number) : 10, minLabel: c?.min_label ?? '', maxLabel: c?.max_label ?? '' };
}

export function optionsOf(q: ReviewQuestion): string[] {
  const o = (q.config as { options?: unknown })?.options;
  return Array.isArray(o) ? o.map(String) : [];
}

function isBlank(q: ReviewQuestion, v: unknown): boolean {
  if (v === undefined || v === null) return true;
  if (typeof v === 'string' && (q.type === 'short_text' || q.type === 'long_text')) return v.trim() === '';
  if (Array.isArray(v) && q.type === 'multi_choice') return v.length === 0;
  return false;
}

/** The problem with one answer, or null when it is fine (or optional and left empty). */
export function problemWith(q: ReviewQuestion, v: unknown): string | null {
  if (isBlank(q, v)) return q.required ? 'Please answer this question.' : null;
  switch (q.type) {
    case 'scale': {
      const { min, max } = scaleRange(q);
      return typeof v === 'number' && v >= min && v <= max ? null : `Choose a score from ${min} to ${max}.`;
    }
    case 'single_choice':
      return typeof v === 'string' && optionsOf(q).includes(v) ? null : 'Choose one of the options.';
    case 'multi_choice':
      return Array.isArray(v) && v.every((x) => optionsOf(q).includes(String(x))) ? null : 'Choose from the options.';
    case 'boolean':
      return typeof v === 'boolean' ? null : 'Choose yes or no.';
    case 'short_text':
    case 'long_text':
      return typeof v === 'string' && v.length <= 20000 ? null : 'That answer is too long.';
    default:
      return 'This question type is not supported.';
  }
}

/** Problems for every active question, keyed by question id (empty when the form can be submitted). */
export function formProblems(questions: ReviewQuestion[], answers: Answers): Record<string, string> {
  const out: Record<string, string> = {};
  for (const q of questions) {
    if (q.archived) continue;
    const p = problemWith(q, answers[q.id]);
    if (p) out[q.id] = p;
  }
  return out;
}

/** The part of a question a judge sees and answers by (not the weight, which only the organizers use). */
const judgeView = (q: ReviewQuestion) => ({ id: q.id, position: q.position, label: q.label, help_text: q.help_text ?? null, type: q.type, config: q.config, required: q.required });

/** True when the two forms differ in anything a judge sees: a question added, removed, reworded, reordered, made required... */
export function formChanged(before: ReviewQuestion[], after: ReviewQuestion[]): boolean {
  const key = (qs: ReviewQuestion[]) => JSON.stringify([...qs].filter((q) => !q.archived).sort((a, b) => a.id.localeCompare(b.id)).map(judgeView));
  return key(before) !== key(after);
}

/** The typed answers that still belong to the form: ids that are no longer on it are dropped, the rest are kept as typed. */
export function answersForForm(questions: ReviewQuestion[], answers: Answers): Answers {
  const ids = new Set(questions.filter((q) => !q.archived).map((q) => q.id));
  return Object.fromEntries(Object.entries(answers).filter(([id]) => ids.has(id)));
}

/** The answers worth sending: only active questions, empty optional answers left out. */
export function answersToSend(questions: ReviewQuestion[], answers: Answers): Answers {
  const out: Answers = {};
  for (const q of questions) {
    if (q.archived) continue;
    const v = answers[q.id];
    if (!isBlank(q, v)) out[q.id] = typeof v === 'string' ? v.trim() : v;
  }
  return out;
}

export const DNF_REASONS: { value: 'too_long' | 'lost_interest' | 'unreadable' | 'other'; label: string }[] = [
  { value: 'too_long', label: 'It is too long for me' },
  { value: 'lost_interest', label: 'I lost interest' },
  { value: 'unreadable', label: 'It is hard to read or broken' },
  { value: 'other', label: 'Another reason' },
];

export const SKIP_REASONS: { value: 'undeclared_trigger' | 'misdeclared_trigger' | 'conflict_of_interest'; label: string; needsTriggers: boolean }[] = [
  { value: 'undeclared_trigger', label: 'It has a content warning the author did not declare', needsTriggers: true },
  { value: 'misdeclared_trigger', label: 'It does not have a content warning the author declared', needsTriggers: true },
  { value: 'conflict_of_interest', label: 'Conflict of interest (for example I recognize the author)', needsTriggers: false },
];

// ── drafts: a judge who reloads mid-review keeps their answers ───────────────────────────────────
// Only the ANSWERS are kept (never the story text), in the browser's localStorage, under one key per assignment.
// They are cleared when the review is submitted, skipped or marked as not finished, when the judge signs out, and
// after 30 days. A draft only fills in answers to questions the form still has.

/** The prefix of every draft key (signOutAndClearSession removes everything under it). */
export const DRAFT_PREFIX = 'rgai_review_draft:';
const DRAFT_MAX_AGE_MS = 30 * 24 * 60 * 60 * 1000;

/** The subset of the Storage interface the drafts need (so tests can pass a fake). */
export interface DraftStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
  readonly length: number;
  key(index: number): string | null;
}

export const draftKey = (assignmentId: string): string => `${DRAFT_PREFIX}${assignmentId}`;

export function saveDraft(storage: DraftStorage | null, assignmentId: string, answers: Answers, now = Date.now()): void {
  if (!storage) return;
  try {
    storage.setItem(draftKey(assignmentId), JSON.stringify({ v: 1, savedAt: now, answers }));
  } catch {
    // storage full or blocked (private mode): the review still works, it just is not saved
  }
}

/** The saved answers for this assignment, limited to the questions of the form; {} when there is none or it is unreadable. */
export function loadDraft(storage: DraftStorage | null, assignmentId: string, questions: ReviewQuestion[], now = Date.now()): Answers {
  if (!storage) return {};
  try {
    const raw = storage.getItem(draftKey(assignmentId));
    if (!raw) return {};
    const parsed = JSON.parse(raw) as { v?: number; savedAt?: number; answers?: Answers };
    if (parsed?.v !== 1 || typeof parsed.savedAt !== 'number' || now - parsed.savedAt > DRAFT_MAX_AGE_MS || typeof parsed.answers !== 'object' || !parsed.answers) return {};
    const ids = new Set(questions.filter((q) => !q.archived).map((q) => q.id));
    return Object.fromEntries(Object.entries(parsed.answers).filter(([id]) => ids.has(id)));
  } catch {
    return {};
  }
}

export function clearDraft(storage: DraftStorage | null, assignmentId: string): void {
  try {
    storage?.removeItem(draftKey(assignmentId));
  } catch {
    // nothing to do
  }
}

/** Removes drafts older than 30 days (and unreadable ones). */
export function pruneDrafts(storage: DraftStorage | null, now = Date.now()): void {
  if (!storage) return;
  try {
    const stale: string[] = [];
    for (let i = 0; i < storage.length; i++) {
      const key = storage.key(i);
      if (!key?.startsWith(DRAFT_PREFIX)) continue;
      try {
        const saved = (JSON.parse(storage.getItem(key) ?? '') as { savedAt?: number }).savedAt;
        if (typeof saved !== 'number' || now - saved > DRAFT_MAX_AGE_MS) stale.push(key);
      } catch {
        stale.push(key);
      }
    }
    stale.forEach((k) => storage.removeItem(k));
  } catch {
    // nothing to do
  }
}

/** The browser's localStorage when it is usable, else null. */
export function browserStorage(): DraftStorage | null {
  try {
    return typeof localStorage === 'undefined' ? null : localStorage;
  } catch {
    return null;
  }
}
