/**
 * Which triggers a picker shows. A retired trigger (active = false) is hidden from every picker, except when the
 * person already has it selected (a judge's blocklist, an author's story): then it stays visible, marked "(retired)",
 * so they can see it and take it off. Hiding it would make saving the form silently drop it, and a retired trigger
 * still counts for matching.
 */
import type { TriggerItem } from './types';

export const pickableTriggers = (all: TriggerItem[], selected: Iterable<string>): TriggerItem[] => {
  const keep = new Set(selected);
  return all.filter((t) => t.active || keep.has(t.slug));
};

/** The label to show in a picker or a list: retired triggers say so. Plain text: escape it where it is shown. */
export const triggerLabel = (t: Pick<TriggerItem, 'label' | 'active'>): string => (t.active ? t.label : `${t.label} (retired)`); // plain text: callers escape it
