/**
 * Shared pieces of the admin screen: what every tab can read and do (AdminContext), the tab contract, and small
 * formatting helpers. Tabs return HTML strings built only from escaped values (esc = escapeHtml).
 */
import { escapeHtml } from '../../common/sanitize';
import type { EventItem, ReviewQuestion, Round, TriggerItem, TriggerReport } from '../types';

export const esc = (v: unknown): string => escapeHtml(v === null || v === undefined ? '' : String(v));

export interface DashboardStats {
  total_stories: number;
  submitted_stories: number;
  total_groups: number;
  complete_groups: number;
  total_reviews: number;
  total_skips: number;
  total_dnfs: number;
}

export interface DashboardCapacity {
  seats_needed: number;
  seats_filled: number;
  shortfall_seats: number;
  registered_judges: number;
  unrestricted_judges: number;
  waiting_more: number;
  paused_judges: number;
}

export interface Dashboard {
  round: Round;
  stats: DashboardStats;
  capacity: DashboardCapacity;
  trigger_queue: TriggerReport[];
}

export type Flash = { type: 'success' | 'error' | 'info'; text: string };

export interface AdminContext {
  events: EventItem[];
  event: EventItem | null;
  /** The round being shown (see `rounds`); null when the event has no round yet. */
  round: Round | null;
  /** Every round of the event, lowest number first. */
  rounds: Round[];
  questions: ReviewQuestion[];
  triggers: TriggerItem[];
  dashboard: Dashboard | null;
  /** The time of the test clock when one is set (only the local simulation sets it), else null. */
  testClock: string | null;
  /** A theme to pre-fill the Triggers tab's add form with (from a trigger report); cleared once added or dismissed. */
  draftTrigger: { label: string; description: string } | null;
  busy: boolean;
  flash(type: Flash['type'], text: string): void;
  /** Runs an action: busy flag, errors shown as a flash, the message it returns shown as a success, then everything reloaded. */
  run(fn: () => Promise<string | void>): Promise<void>;
  /** Reloads the event, round, questions and dashboard (and the active tab's own data). */
  reload(): Promise<void>;
  rerender(): void;
  /** Show another round of the event; the next reload loads it. */
  selectRound(number: number): void;
  /** Switch to another tab. */
  go(tab: string): void;
}

export interface AdminTab {
  id: string;
  label: string;
  /** Loads the tab's own data; called when the tab is shown and after every reload. */
  load?(ctx: AdminContext): Promise<void>;
  render(ctx: AdminContext): string;
  /** A click (or change) on an element with data-action="name". */
  onAction?(name: string, el: HTMLElement, ctx: AdminContext, root: ParentNode): void | Promise<void>;
}

export function fmtDateTime(iso: string | null | undefined): string {
  if (!iso) return '';
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? '' : d.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
}

/** An ISO time as the value of an <input type="datetime-local"> (local time). */
export function toLocalInput(iso: string | null | undefined): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const p = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;
}

/** An <input type="datetime-local"> value as an ISO time, or null when empty. */
export function fromLocalInput(value: string): string | null {
  if (!value) return null;
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

/** An image URL we accept: https only, no spaces, quotes or angle brackets (the database checks the same). */
export function isSafeImageUrl(url: string): boolean {
  return /^https:\/\/[^\s<>"]+$/.test(url);
}

export const triggerTags = (slugs: string[], triggers: TriggerItem[]): string =>
  slugs.length ? slugs.map((s) => `<span class="tag">${esc(triggers.find((t) => t.slug === s)?.label ?? s)}</span>`).join('') : '<span class="tag tag-none">none</span>';
