/**
 * The review-form editor on the "Round setup" tab (docs/story-review-next.md §2): list, add, edit, archive/restore,
 * delete, reorder, a preview of the form as a judge sees it, and the log of changes.
 *
 * What may change depends on the round's form state, which the database decides (guard_question_write):
 *   before  no review submitted yet: everything,
 *   started reviews exist: weights, wording, order, required, positive options, added options, archiving; new questions
 *           only unscored; no type, scale range or option text changes,
 *   closed  the round is closed: read-only.
 * This screen only mirrors those rules so that a control that is not allowed is disabled and says why. The database is
 * the authority: whatever it refuses is shown as the error message.
 */
import { addQuestion, archiveQuestion, deleteQuestion, questionChanges, questionForm, reorderQuestions, updateQuestion } from '../api';
import { optionsOf, scaleRange } from '../review-form';
import type { QuestionChange, QuestionForm, QuestionType, ReviewQuestion } from '../types';
import { esc, fmtDateTime, type AdminContext } from './context';

const TYPE_NAMES: Record<QuestionType, string> = {
  scale: 'Scale (a number)', single_choice: 'One choice', multi_choice: 'Several choices', boolean: 'Yes / no', short_text: 'Short text', long_text: 'Long text',
};
const FIELD_NAMES: Record<QuestionChange['field'], string> = {
  created: 'added', deleted: 'deleted', label: 'question', help_text: 'help text', type: 'type', config: 'settings', positive: 'counts as positive', required: 'required', weight: 'weight', archived: 'archived', position: 'place',
};

const cfg = (q: ReviewQuestion): Record<string, unknown> => (q.config ?? {}) as Record<string, unknown>;
const isRecommendation = (q: ReviewQuestion): boolean => cfg(q).purpose === 'recommendation';
const positiveOf = (q: ReviewQuestion): string[] => (Array.isArray(cfg(q).positive) ? (cfg(q).positive as unknown[]).map(String) : []);
const shorten = (v: string | null, n = 70): string => (v === null ? '' : v.length > n ? `${v.slice(0, n)}…` : v);

export class QuestionEditor {
  private form: QuestionForm | null = null;
  private changes: QuestionChange[] = [];
  /** The id of the question being edited, 'new' for a new one, or null. */
  private editing: string | null = null;
  private previewing = false;
  /** The type chosen in the open form (it decides which fields show). */
  private draftType: QuestionType = 'scale';
  /** What was typed in the open form when the type was changed (changing it re-draws the form). */
  private typed: { label: string; help: string } | null = null;

  async load(ctx: AdminContext) {
    this.form = null;
    this.changes = [];
    if (!ctx.round) return;
    [this.form, this.changes] = await Promise.all([questionForm(ctx.round.id), questionChanges(ctx.round.id, 30)]);
    if (this.editing && this.editing !== 'new' && !ctx.questions.some((q) => q.id === this.editing)) this.editing = null;
  }

  // ── what is allowed ──────────────────────────────────────────────────────────────────────────
  private get state(): QuestionForm['state'] {
    return this.form?.state ?? 'before';
  }
  private reviews(): string {
    const n = this.form?.submitted_reviews ?? 0;
    return `${n} ${n === 1 ? 'review is' : 'reviews are'} submitted in this round`;
  }
  /** Why a field cannot be edited right now, or '' when it can. */
  private locked(what: 'any' | 'type' | 'scale' | 'option-text' | 'purpose' | 'new-weight'): string {
    if (this.state === 'closed') return 'This round is closed, so its review form is read-only.';
    if (this.state === 'started') {
      if (what === 'type') return `${this.reviews()}, so the type cannot change.`;
      if (what === 'scale') return `${this.reviews()}, so the ends of the scale cannot change (a 7 would mean something else). The end labels can.`;
      if (what === 'option-text') return `${this.reviews()}; answers store an option's text, so options cannot be renamed or removed. You can add options.`;
      if (what === 'purpose') return `${this.reviews()}, so which question is the recommendation cannot change.`;
      if (what === 'new-weight') return `${this.reviews()}; earlier reviews lack an answer to a new question, so it cannot be scored.`;
    }
    return '';
  }
  /** Why a question cannot be removed (archived, retyped or turned to weight 0), or ''. */
  private lastScoredReason(ctx: AdminContext, q: ReviewQuestion): string {
    const scored = (x: ReviewQuestion) => x.type === 'scale' && x.weight > 0 && !x.archived;
    if (ctx.round?.status !== 'reviewing' || !scored(q)) return '';
    return ctx.questions.filter(scored).length <= 1 ? 'A round that is reviewing must keep at least one scored question.' : '';
  }

  // ── rendering ────────────────────────────────────────────────────────────────────────────────
  render(ctx: AdminContext): string {
    const all = [...ctx.questions].sort((a, b) => a.position - b.position);
    const active = all.filter((q) => !q.archived);
    const closed = this.state === 'closed';
    if (!all.length && !this.editing) {
      return `<div class="section"><h3>Review form</h3><div class="alert alert-warning">This round has no questions yet, so judges cannot review.</div>
        <div class="row"><button type="button" class="btn btn-primary" data-action="seed-questions" ${ctx.busy || closed ? 'disabled' : ''}>Add the default review form</button>
        <button type="button" class="btn btn-secondary" data-action="edit-question" data-id="new" ${ctx.busy || closed ? 'disabled' : ''}>Start with an empty form</button></div>
        <p class="muted">The default is last year's nine 0–10 scores (“How scary is it?” counts 5×, the others 1×) and the four-option recommendation.</p></div>`;
    }
    return `
      <div class="section">
        <div class="row" style="justify-content: space-between; margin-bottom: 0.5rem;">
          <h3 style="margin:0;">Review form <span class="muted" style="font-weight:400;">(${active.length} ${active.length === 1 ? 'question' : 'questions'}${all.length > active.length ? `, ${all.length - active.length} archived` : ''})</span></h3>
          <div class="row"><button type="button" class="btn btn-secondary btn-sm" data-action="toggle-preview">${this.previewing ? 'Hide the preview' : 'Preview as a judge'}</button>
            <button type="button" class="btn btn-primary btn-sm" data-action="edit-question" data-id="new" ${ctx.busy || closed || this.editing === 'new' ? 'disabled' : ''} ${closed ? `title="${esc(this.locked('any'))}"` : ''}>+ Add a question</button></div>
        </div>
        ${this.stateNote()}
        ${this.editing === 'new' ? this.editForm(ctx, null) : ''}
        <div class="table-wrap"><table><thead><tr><th>Order</th><th>Question</th><th class="num">Weight</th><th>Required</th><th></th></tr></thead><tbody>
          ${all.map((q, i) => (this.editing === q.id ? `<tr><td></td><td colspan="4">${this.editForm(ctx, q)}</td></tr>` : this.row(ctx, q, i, all.length))).join('')}
        </tbody></table></div>
        ${this.previewing ? this.preview(active) : ''}
        ${this.changes.length ? `<details style="margin-top: 1rem;"><summary class="muted" style="cursor:pointer;">Recent changes to this form (${this.changes.length})</summary>
          <div class="table-wrap"><table><thead><tr><th>When</th><th>Who</th><th>Question</th><th>What</th><th>From</th><th>To</th></tr></thead><tbody>
            ${this.changes.map((c) => `<tr><td>${esc(fmtDateTime(c.changed_at))}</td><td>${esc(c.changed_by_name ?? '')}</td><td>${esc(shorten(c.question_label, 40))}</td><td>${esc(FIELD_NAMES[c.field] ?? c.field)}</td><td>${esc(shorten(c.old_value))}</td><td>${esc(shorten(c.new_value))}</td></tr>`).join('')}
          </tbody></table></div></details>` : ''}
      </div>`;
  }

  private stateNote(): string {
    if (this.state === 'closed') return '<div class="alert alert-info">This round is closed, so its review form is a record and cannot be changed.</div>';
    if (this.state === 'started') {
      return `<div class="alert alert-warning"><b>${esc(this.reviews())}.</b> You can still change the weights (scores are re-computed at once), the wording, the order, whether a question is required, which recommendations count as positive, add options, add questions that are not scored, and archive questions. You cannot change types, scale ends, option texts or add a scored question. When you edit wording, fix the wording, not the meaning: earlier answers were given to the old words.</div>`;
    }
    return '<div class="alert alert-info">No review is submitted yet, so everything can change. Once the first review is submitted, types, scales, option texts and new scored questions are locked.</div>';
  }

  private row(ctx: AdminContext, q: ReviewQuestion, i: number, n: number): string {
    const closed = this.state === 'closed';
    const lastScored = this.lastScoredReason(ctx, q);
    const bits: string[] = [TYPE_NAMES[q.type] ?? q.type];
    if (q.type === 'scale') {
      const r = scaleRange(q);
      bits.push(`${r.min} to ${r.max}${r.minLabel || r.maxLabel ? ` (${r.minLabel} … ${r.maxLabel})` : ''}`);
    }
    if (q.type === 'single_choice' || q.type === 'multi_choice') bits.push(optionsOf(q).map((o) => (positiveOf(q).includes(o) ? `${o} ✓` : o)).join(' · '));
    const disabledTitle = (why: string) => (why ? `title="${esc(why)}"` : '');
    return `<tr style="${q.archived ? 'opacity: 0.6;' : ''}">
      <td style="white-space:nowrap;"><button type="button" class="btn btn-secondary btn-sm" data-action="move-question" data-id="${esc(q.id)}" data-dir="-1" aria-label="Move up" ${ctx.busy || closed || i === 0 ? 'disabled' : ''} ${disabledTitle(closed ? this.locked('any') : '')}>↑</button>
        <button type="button" class="btn btn-secondary btn-sm" data-action="move-question" data-id="${esc(q.id)}" data-dir="1" aria-label="Move down" ${ctx.busy || closed || i === n - 1 ? 'disabled' : ''} ${disabledTitle(closed ? this.locked('any') : '')}>↓</button></td>
      <td><b>${esc(q.label)}</b> ${q.required ? '<span class="muted">*</span>' : ''} ${q.archived ? '<span class="badge badge-warning">archived</span>' : ''} ${isRecommendation(q) ? '<span class="badge badge-info">recommendation</span>' : ''}
        ${q.help_text ? `<div class="muted">${esc(q.help_text)}</div>` : ''}<div class="muted">${esc(bits.join(' · '))}</div></td>
      <td class="num">${q.type === 'scale' ? esc(q.weight) : ''}</td><td>${q.required ? 'yes' : 'no'}</td>
      <td><div class="row">
        <button type="button" class="btn btn-secondary btn-sm" data-action="edit-question" data-id="${esc(q.id)}" ${ctx.busy || closed ? 'disabled' : ''} ${disabledTitle(closed ? this.locked('any') : '')}>Edit</button>
        ${q.archived
          ? `<button type="button" class="btn btn-secondary btn-sm" data-action="archive-question" data-id="${esc(q.id)}" data-archived="false" ${ctx.busy || closed ? 'disabled' : ''} ${disabledTitle(closed ? this.locked('any') : '')}>Restore</button>`
          : `<button type="button" class="btn btn-secondary btn-sm" data-action="archive-question" data-id="${esc(q.id)}" data-archived="true" ${ctx.busy || closed || lastScored ? 'disabled' : ''} ${disabledTitle(closed ? this.locked('any') : lastScored || 'Hides it from judges and stops scoring it; the answers are kept')}>Archive</button>`}
        ${this.state === 'before'
          ? `<button type="button" class="btn btn-danger btn-sm" data-action="delete-question" data-id="${esc(q.id)}" data-label="${esc(q.label)}" ${ctx.busy || lastScored ? 'disabled' : ''} ${disabledTitle(lastScored)}>Delete</button>`
          : `<button type="button" class="btn btn-danger btn-sm" disabled title="${esc(closed ? this.locked('any') : `${this.reviews()}: archive it instead, the answers are kept.`)}">Delete</button>`}
      </div></td></tr>`;
  }

  /** The form for a new question (q = null) or an existing one. Disabled fields say why. */
  private editForm(ctx: AdminContext, q: ReviewQuestion | null): string {
    const type = q ? q.type : this.draftType;
    const started = this.state === 'started';
    const c = q ? cfg(q) : {};
    const range = q ? scaleRange(q) : { min: 0, max: 10, minLabel: '', maxLabel: '' };
    const options = q ? optionsOf(q) : [];
    const positive = q ? positiveOf(q) : [];
    const why = (reason: string) => (reason ? `<div class="hint bad">${esc(reason)}</div>` : '');
    const dis = (reason: string) => (reason ? 'disabled' : '');
    const typeWhy = q ? this.locked('type') : '';
    const scaleWhy = q ? this.locked('scale') : '';
    const weightWhy = !q && started ? this.locked('new-weight') : '';
    const lastScored = q ? this.lastScoredReason(ctx, q) : '';
    const isChoice = type === 'single_choice' || type === 'multi_choice';
    return `
      <div class="section" style="margin: 0.75rem 0;">
        <h3>${q ? 'Edit the question' : 'Add a question'}</h3>
        ${started && q ? '<div class="alert alert-warning">Earlier reviews answered the old wording. Change the wording to be clearer, not to mean something else.</div>' : ''}
        <div class="form-grid">
          <div class="field" style="grid-column: 1 / -1;"><label for="qe-label">Question</label><input id="qe-label" maxlength="300" value="${esc(this.typed?.label ?? q?.label ?? '')}" /></div>
          <div class="field" style="grid-column: 1 / -1;"><label for="qe-help">Help text (optional, shown under the question)</label><input id="qe-help" maxlength="1000" value="${esc(this.typed?.help ?? q?.help_text ?? '')}" /></div>
          <div class="field"><label for="qe-type">Type</label>
            <select id="qe-type" data-action="question-type" ${dis(typeWhy)}>${(Object.keys(TYPE_NAMES) as QuestionType[]).map((t) => `<option value="${t}" ${t === type ? 'selected' : ''}>${esc(TYPE_NAMES[t])}</option>`).join('')}</select>${why(typeWhy)}</div>
          <div class="field"><label for="qe-required">Required</label><select id="qe-required"><option value="yes" ${!q || q.required ? 'selected' : ''}>Yes</option><option value="no" ${q && !q.required ? 'selected' : ''}>No</option></select>
            ${started ? '<div class="hint">Turning it on applies to reviews submitted from now on; earlier reviews stay valid.</div>' : ''}</div>
          ${type === 'scale' ? `
            <div class="field"><label for="qe-weight">Weight (0 = not scored)</label><input id="qe-weight" type="number" min="0" step="0.5" value="${esc(q?.weight ?? 0)}" ${dis(weightWhy)} />${why(weightWhy)}
              ${lastScored ? `<div class="hint bad">${esc(lastScored)}</div>` : '<div class="hint">A weight changes every score in the round at once.</div>'}</div>
            <div class="field"><label for="qe-min">Lowest score</label><input id="qe-min" type="number" value="${esc(range.min)}" ${dis(scaleWhy)} />${why(scaleWhy)}</div>
            <div class="field"><label for="qe-max">Highest score</label><input id="qe-max" type="number" value="${esc(range.max)}" ${dis(scaleWhy)} /></div>
            <div class="field"><label for="qe-minlabel">Label of the lowest score</label><input id="qe-minlabel" maxlength="40" value="${esc(range.minLabel)}" /></div>
            <div class="field"><label for="qe-maxlabel">Label of the highest score</label><input id="qe-maxlabel" maxlength="40" value="${esc(range.maxLabel)}" /></div>` : ''}
          ${isChoice ? this.optionFields(q, type, options, positive, started, c) : ''}
        </div>
        <div class="row" style="margin-top: 0.9rem;">
          <button type="button" class="btn btn-primary" data-action="save-question" data-id="${esc(q?.id ?? 'new')}" ${ctx.busy ? 'disabled' : ''}>${q ? 'Save' : 'Add the question'}</button>
          <button type="button" class="btn btn-secondary" data-action="cancel-question">Cancel</button>
        </div>
      </div>`;
  }

  private optionFields(q: ReviewQuestion | null, type: QuestionType, options: string[], positive: string[], started: boolean, c: Record<string, unknown>): string {
    const optWhy = q ? this.locked('option-text') : '';
    const purposeWhy = q ? this.locked('purpose') : started ? this.locked('purpose') : '';
    return `
      <div class="field" style="grid-column: 1 / -1;">
        ${started && q ? `<label>Options (cannot be renamed or removed)</label><div>${options.map((o) => `<span class="tag">${esc(o)}</span>`).join('')}</div>
            <label for="qe-newoptions" style="margin-top:0.5rem;">Add options (one per line)</label><textarea id="qe-newoptions" rows="2"></textarea>
            <div class="hint bad">${esc(optWhy)}</div>`
          : `<label for="qe-options">Options (one per line, at least two)</label><textarea id="qe-options" rows="4">${esc(options.join('\n'))}</textarea>`}
      </div>
      ${type === 'single_choice' ? `
        <div class="field" style="grid-column: 1 / -1;">
          <label><input type="checkbox" id="qe-purpose" ${c.purpose === 'recommendation' ? 'checked' : ''} ${purposeWhy ? 'disabled' : ''} /> This is the recommendation question (the results count its positive options)</label>${why2(purposeWhy)}
          ${options.length ? `<div style="margin-top:0.4rem;"><span class="muted">Counts as a positive recommendation:</span> ${options.map((o) => `<label style="margin-right:0.75rem; font-weight:400;"><input type="checkbox" class="qe-positive" value="${esc(o)}" ${positive.includes(o) ? 'checked' : ''} /> ${esc(o)}</label>`).join('')}</div>` : ''}
        </div>` : ''}`;
  }

  private preview(active: ReviewQuestion[]): string {
    const control = (q: ReviewQuestion): string => {
      switch (q.type) {
        case 'scale': {
          const r = scaleRange(q);
          const n = Math.min(r.max - r.min + 1, 101);
          return `<div class="row" style="gap:0.25rem;">${Array.from({ length: n }, (_, k) => `<span class="badge">${r.min + k}</span>`).join('')}</div><div class="muted">${esc(r.minLabel)} … ${esc(r.maxLabel)}</div>`;
        }
        case 'single_choice': return optionsOf(q).map((o) => `<div><input type="radio" disabled /> ${esc(o)}</div>`).join('');
        case 'multi_choice': return optionsOf(q).map((o) => `<div><input type="checkbox" disabled /> ${esc(o)}</div>`).join('');
        case 'boolean': return '<div><input type="radio" disabled /> Yes <input type="radio" disabled /> No</div>';
        case 'short_text': return '<input type="text" disabled style="width:100%;" />';
        default: return '<textarea disabled rows="2" style="width:100%;"></textarea>';
      }
    };
    return `<div class="section" style="margin-top: 1rem; background:#f8fafc;"><h3>As a judge sees it</h3>
      ${active.length ? active.map((q) => `<div style="margin-bottom: 1rem;"><div><b>${esc(q.label)}</b> ${q.required ? '<span class="bad">*</span>' : ''}</div>${q.help_text ? `<div class="muted">${esc(q.help_text)}</div>` : ''}${control(q)}</div>`).join('') : '<div class="empty">No active question.</div>'}
      <p class="muted" style="margin-bottom:0;">Read-only: nothing here is saved.</p></div>`;
  }

  // ── actions ──────────────────────────────────────────────────────────────────────────────────
  async onAction(name: string, el: HTMLElement, ctx: AdminContext, root: ParentNode): Promise<boolean> {
    const id = el.getAttribute('data-id') ?? '';
    const question = ctx.questions.find((x) => x.id === id);
    switch (name) {
      case 'toggle-preview':
        this.previewing = !this.previewing;
        ctx.rerender();
        return true;
      case 'edit-question':
        this.typed = null;
        this.editing = id;
        this.draftType = question?.type ?? 'scale';
        ctx.rerender();
        return true;
      case 'cancel-question':
        this.typed = null;
        this.editing = null;
        ctx.rerender();
        return true;
      case 'question-type':
        this.typed = { label: (root.querySelector<HTMLInputElement>('#qe-label')?.value ?? ''), help: (root.querySelector<HTMLInputElement>('#qe-help')?.value ?? '') };
        this.draftType = (el as HTMLSelectElement).value as QuestionType;
        ctx.rerender();
        return true;
      case 'save-question':
        await this.save(ctx, root, question ?? null);
        return true;
      case 'archive-question':
        if (!question?.updated_at) return true;
        await ctx.run(async () => {
          const archive = el.getAttribute('data-archived') === 'true';
          await archiveQuestion(question.id, question.updated_at!, archive);
          return archive ? 'Archived: judges no longer see it and it is no longer scored. The answers are kept.' : 'Restored.';
        });
        return true;
      case 'delete-question':
        if (!question?.updated_at) return true;
        if (!confirm(`Delete “${el.getAttribute('data-label') ?? ''}”? No review is submitted yet, so nothing is lost. This cannot be undone.`)) return true; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        await ctx.run(async () => {
          await deleteQuestion(question.id, question.updated_at!);
          return 'Deleted.';
        });
        return true;
      case 'move-question': {
        const all = [...ctx.questions].sort((a, b) => a.position - b.position);
        const i = all.findIndex((x) => x.id === id);
        const j = i + Number(el.getAttribute('data-dir'));
        if (i < 0 || j < 0 || j >= all.length || !ctx.round) return true;
        [all[i], all[j]] = [all[j], all[i]];
        await ctx.run(async () => {
          await reorderQuestions(ctx.round!.id, all.map((x) => x.id));
          return 'Order saved.';
        });
        return true;
      }
    }
    return false;
  }

  /** Reads the open form and sends only what changed. */
  private async save(ctx: AdminContext, root: ParentNode, q: ReviewQuestion | null) {
    const val = (id: string) => (root.querySelector<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>(`#${id}`)?.value ?? '').trim();
    const has = (id: string) => Boolean(root.querySelector(`#${id}`));
    const type = (has('qe-type') ? val('qe-type') : q?.type ?? 'scale') as QuestionType;
    const label = val('qe-label');
    if (!label) return ctx.flash('error', 'Type the question first.');
    const required = val('qe-required') !== 'no';

    // settings: start from what the question has (keys this screen does not know stay), then set what the form shows
    const config: Record<string, unknown> = { ...(q && q.type === type ? cfg(q) : {}) };
    let weight = q?.weight ?? 0;
    if (type === 'scale') {
      if (has('qe-min')) config.min = Number(val('qe-min'));
      if (has('qe-max')) config.max = Number(val('qe-max'));
      config.min_label = val('qe-minlabel');
      config.max_label = val('qe-maxlabel');
      if (has('qe-weight')) weight = Number(val('qe-weight')) || 0;
    } else {
      weight = 0;
      for (const k of ['min', 'max', 'min_label', 'max_label']) delete config[k];
    }
    if (type === 'single_choice' || type === 'multi_choice') {
      const lines = (id: string) => val(id).split('\n').map((s) => s.trim()).filter(Boolean);
      const options = has('qe-options') ? lines('qe-options') : [...optionsOf(q as ReviewQuestion), ...lines('qe-newoptions').filter((o) => !optionsOf(q as ReviewQuestion).includes(o))];
      config.options = options;
      if (type === 'single_choice') {
        const positive = Array.from(root.querySelectorAll<HTMLInputElement>('.qe-positive:checked')).map((b) => b.value).filter((o) => options.includes(o));
        if (has('qe-purpose') && !root.querySelector<HTMLInputElement>('#qe-purpose:disabled')) {
          if (root.querySelector<HTMLInputElement>('#qe-purpose')?.checked) config.purpose = 'recommendation';
          else delete config.purpose;
        }
        if (config.purpose === 'recommendation') config.positive = positive;
        else delete config.positive;
      } else {
        delete config.purpose;
        delete config.positive;
      }
    } else {
      delete config.options;
      delete config.purpose;
      delete config.positive;
    }

    if (!q) {
      return ctx.run(async () => {
        await addQuestion(ctx.round!.id, { label, help_text: val('qe-help') || null, type, config, required, weight });
        this.editing = null;
        this.typed = null;
        return 'Question added at the end of the form.';
      });
    }
    const changes: Record<string, unknown> = {};
    if (label !== q.label) changes.label = label;
    if (val('qe-help') !== (q.help_text ?? '')) changes.help_text = val('qe-help');
    if (type !== q.type) changes.type = type;
    if (JSON.stringify(sortKeys(config)) !== JSON.stringify(sortKeys(cfg(q))) || type !== q.type) changes.config = config;
    if (required !== q.required) changes.required = required;
    if (weight !== q.weight) changes.weight = weight;
    if (!Object.keys(changes).length) {
      this.editing = null;
      return ctx.rerender();
    }
    if (!q.updated_at) return ctx.flash('error', 'Reload the page and try again.');
    return ctx.run(async () => {
      await updateQuestion(q.id, q.updated_at!, changes);
      this.editing = null;
      this.typed = null;
      return 'Saved.';
    });
  }
}

const why2 = (reason: string): string => (reason ? `<div class="hint bad">${esc(reason)}</div>` : '');

function sortKeys(o: Record<string, unknown>): Record<string, unknown> {
  return Object.fromEntries(Object.entries(o).sort(([a], [b]) => a.localeCompare(b)));
}
