import '../account/rg-sign-in-prompt';
import './components/account-component';
import './components/submit-component';
import './components/review-component';
import './components/admin-component';
import { getSupabaseClient } from '../common/supabase-client';
import { validateAndGetSession } from '../common/auth-utils';

export type AppView = 'account' | 'submit' | 'review' | 'admin';

const SIGN_IN_TEXT: Record<AppView, [heading: string, message: string]> = {
  account: ['Your account', 'Sign in or create an account to see your account settings.'],
  submit: ['Submit a story', 'Sign in or create an account to submit your story.'],
  review: ['Review stories', 'Sign in to see the stories assigned to you.'],
  admin: ['Story review admin', 'Sign in with an organizer account.'],
};

export class RgaiAppElement extends HTMLElement {
  private view: AppView = 'account';
  /** Whose screen is on show: a user id, null for the sign-in prompt, undefined before the first render. */
  private shownUser: string | null | undefined = undefined;
  private unsubscribe: (() => void) | null = null;

  static observedAttributes = ['data-view'];

  connectedCallback() {
    this.view = (this.getAttribute('data-view') as AppView) || 'account';
    this.initApp();
  }

  /** A screen asked for (the harness's view links do this): show it for whoever is on show. Setting the same view
   *  again rebuilds it, which is how a page asks for a fresh copy (for example after a role change). */
  attributeChangedCallback(_name: string, _oldValue: string | null, newValue: string | null) {
    this.view = (newValue as AppView) || 'account';
    if (this.shownUser === undefined) return; // first render still to come; it reads this.view
    if (this.shownUser) this.renderView();
    else this.renderAuth();
  }

  disconnectedCallback() {
    this.unsubscribe?.();
    this.unsubscribe = null;
  }

  private onAuthChanged = (e: Event) => {
    this.show((e as CustomEvent).detail?.user?.id ?? null);
  };

  private async initApp() {
    if (this.unsubscribe) return; // already listening (connected twice)
    window.addEventListener('rgai-auth-changed', this.onAuthChanged);
    this.unsubscribe = () => window.removeEventListener('rgai-auth-changed', this.onAuthChanged);

    // There is no way around sign-in: no URL flag, no global config. A request without a valid session shows the sign-in form.
    try {
      const { user } = await validateAndGetSession();
      if (!this.unsubscribe) return; // removed from the page while the session was being checked
      this.show(user?.id ?? null);

      // supabase-js fires SIGNED_IN again every time the tab becomes visible (it re-checks the session), and
      // TOKEN_REFRESHED about once an hour. Neither changes who is signed in, so show() ignores them: rebuilding the
      // screen would throw away whatever the person was doing (a story being written, a review half filled in).
      const { data } = getSupabaseClient().auth.onAuthStateChange((_event, session) => {
        this.show(session?.user?.id ?? null);
      });
      const removeWindowListener = this.unsubscribe;
      this.unsubscribe = () => {
        removeWindowListener();
        data.subscription.unsubscribe();
      };
    } catch (err) {
      console.warn('Supabase auth error. Rendering sign-in:', err);
      this.show(null);
    }
  }

  /** Renders the screen for this user (or the sign-in prompt for null), but only when that is not already on show. */
  private show(userId: string | null) {
    if (userId === this.shownUser) return;
    this.shownUser = userId;
    if (userId) this.renderView();
    else this.renderAuth();
  }

  /** Signed out: a prompt whose buttons open the site-wide sign-in dialog (the same one as the header button).
   *  Signing in there fires `rgai-auth-changed` on window, which the listener above turns into show(user). */
  private renderAuth() {
    const [heading, message] = SIGN_IN_TEXT[this.view] ?? SIGN_IN_TEXT.account;
    const prompt = document.createElement('rg-sign-in-prompt');
    prompt.setAttribute('heading', heading);
    prompt.setAttribute('message', message);
    this.replaceChildren(prompt);
  }

  private renderView() {
    switch (this.view) {
      case 'account':
        this.innerHTML = `<rgai-account></rgai-account>`;
        break;
      case 'submit':
        this.innerHTML = `<rgai-submit></rgai-submit>`;
        break;
      case 'review':
        this.innerHTML = `<rgai-review></rgai-review>`;
        break;
      case 'admin':
        this.innerHTML = `<rgai-admin></rgai-admin>`;
        break;
      default:
        this.innerHTML = `<rgai-account></rgai-account>`;
    }
  }
}

if (!customElements.get('rgai-app')) {
  customElements.define('rgai-app', RgaiAppElement);
}

// Auto-mount function for Squarespace pages having <div id="rgai-app" data-view="...">
export function mountRgaiApp() {
  const mountPoints = document.querySelectorAll<HTMLElement>('#rgai-app:not([data-mounted="true"])');
  mountPoints.forEach((mountPoint) => {
    mountPoint.setAttribute('data-mounted', 'true');
    const view = mountPoint.getAttribute('data-view') || 'account';
    const app = document.createElement('rgai-app');
    app.setAttribute('data-view', view);
    mountPoint.appendChild(app);
  });
}

// Automatically mount on page load and on Squarespace Ajax navigation (mercury:load)
if (typeof window !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', mountRgaiApp);
  } else {
    mountRgaiApp();
  }
  window.addEventListener('mercury:load', mountRgaiApp);
}
