interface GroupStoryItem {
  assignment_id: string;
  story_id: string;
  title: string;
  summary: string;
  trigger_slugs: string[];
  status: 'assigned' | 'submitted' | 'skipped' | 'dnf' | 'released';
  submitted_at?: string;
  skip_reason?: string;
  dnf_reason?: string;
}

interface ActiveGroupData {
  has_group: boolean;
  group?: { id: string; number: number; trigger_slugs: string[]; status: string };
  group_assignment?: { id: string; status: string; assigned_at: string; first_opened_at?: string; completed_at?: string };
  stories?: GroupStoryItem[];
  progress?: { total: number; done: number; completed_groups_count: number };
  /** The server's answer to "would Send me more be accepted" (a group finished or left, none unfinished); the screen shows nothing else. */
  can_request_more?: boolean;
  round_judge?: { intake: 'open' | 'paused'; bonus_groups: number; more_requested_at?: string | null; paused_at?: string; pause_reason?: string };
}

interface AssignmentDetail {
  assignment: { id: string; status: string; answers: Answers; skip_reason?: string; skip_note?: string; dnf_reason?: string };
  story: { id: string; title: string; summary: string; content: string; trigger_slugs: string[] };
  questions: ReviewQuestion[];
}

type Modal = null | 'skip' | 'dnf' | 'leave' | 'pause' | 'unregister' | 'stop';

