/**
 * The "My account" screen as HTML. Every value that came from the database or the user (the display name, the
 * trigger slugs, labels and descriptions) goes through escapeHtml, in text and in attributes alike.
 */
import { escapeHtml as esc } from '../common/sanitize';
import { pickableTriggers, triggerLabel } from './triggers';
import type { Profile, TriggerItem } from './types';

export function accountHtml(profile: Pick<Profile, 'display_name' | 'default_blocked_triggers' | 'email_digest' | 'newsletter_opt_in'>, triggers: TriggerItem[]): string {
  const blocked = new Set(profile.default_blocked_triggers || []);
  return `
      <div class="account-card">
        <div class="header">
          <h2 class="title">My Account</h2>
        </div>

        <div id="status-msg" class="msg"></div>

        <form id="account-form">
          <div class="section">
            <div class="form-group">
              <label for="display-name">Display Name</label>
              <input type="text" id="display-name" value="${esc(profile.display_name || '')}" required />
            </div>
          </div>

          <div class="section">
            <h3 class="section-title">Default Content Avoidance (Triggers)</h3>
            <p class="section-desc">
              Stories with these themes will automatically be excluded when assigning stories to review.
              You can also customize this per event.
            </p>
            <div class="trigger-list">
              ${pickableTriggers(triggers, blocked)
                .map(
                  (t) => `
                <label class="trigger-item">
                  <input type="checkbox" name="trigger" value="${esc(t.slug)}" ${blocked.has(t.slug) ? 'checked' : ''} />
                  <div class="trigger-info">
                    <div class="trigger-label">${esc(triggerLabel(t))}</div>
                    ${t.description ? `<div class="trigger-desc">${esc(t.description)}</div>` : ''}
                  </div>
                </label>
              `,
                )
                .join('')}
            </div>
          </div>

          <div class="section">
            <h3 class="section-title">Notifications & Updates</h3>
            <div class="checkbox-row">
              <input type="checkbox" id="email-digest" ${profile.email_digest ? 'checked' : ''} />
              <label for="email-digest" style="margin:0;">
                <strong>Daily Review Digest</strong>
                <div class="trigger-desc">Receive a daily status digest when you have stories pending review.</div>
              </label>
            </div>

            <div class="checkbox-row">
              <input type="checkbox" id="newsletter-opt-in" ${profile.newsletter_opt_in ? 'checked' : ''} />
              <label for="newsletter-opt-in" style="margin:0;">
                <strong>Real Good AI Newsletter</strong>
                <div class="trigger-desc">Opt-in to event announcements, results, and calls for submissions.</div>
              </label>
            </div>
          </div>

          <button type="submit" class="btn-save" id="btn-save">Save Profile Changes</button>
        </form>
      </div>
    `;
}
