/**
 * The "Capacity" tab: are there enough judges, who holds what, who is stuck. Groups with their seats and progress,
 * judges with their load and how many groups they could still take, and every seat, with the admin's buttons
 * (seat a judge by hand, release a seat, force-complete a group, grant or take back bonus groups).
 */
import { adminGroups, adminJudges, adminSeats, assignSeat, forceCompleteGroup, groupResults, nudgeJudge, previewGroups, releaseSeat, setBonusGroups } from '../api';
import type { AdminGroup, AdminJudge, AdminSeat, GroupResult, PreviewGroup } from '../types';
import { esc, fmtDateTime, triggerTags, type AdminContext, type AdminTab } from './context';

const median = (v: number[]): number => {
  if (!v.length) return 0;
  const s = [...v].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

export class CapacityTab implements AdminTab {
  id = 'capacity';
  label = 'Capacity';

  private groups: AdminGroup[] = [];
  private seats: AdminSeat[] = [];
  private judges: AdminJudge[] = [];
  private results = new Map<string, GroupResult>();
  private preview = new Map<string, PreviewGroup>();

  async load(ctx: AdminContext) {
    this.groups = [];
    this.seats = [];
    this.judges = [];
    this.results.clear();
    this.preview.clear();
    if (!ctx.round) return;
    const id = ctx.round.id;
    const [judges, groups, seats, results, preview] = await Promise.all([adminJudges(id), adminGroups(id), adminSeats(id), groupResults(id), previewGroups(id)]);
    this.judges = judges;
    this.groups = groups;
    this.seats = seats;
    for (const r of results) this.results.set(r.group_id, r);
    for (const g of preview.groups ?? []) this.preview.set(g.group_id, g);
  }

  render(ctx: AdminContext): string {
    if (!ctx.round) return '<div class="empty">Create the round on the “Round setup” tab first.</div>';
    const cap = ctx.dashboard?.capacity;
    const st = ctx.dashboard?.stats;
    const target = ctx.round.target_judges_per_group;
    const eligible = [...this.preview.values()].map((p) => p.eligible_judges_count);
    const noEligible = this.judges.filter((j) => j.accepted_at && j.eligible_groups === 0 && this.groups.some((g) => g.status !== 'draft'));
    return `
      <div class="metrics">
        <div class="metric"><b>${cap?.seats_filled ?? 0} / ${cap?.seats_needed ?? 0}</b><span>seats filled / needed</span></div>
        <div class="metric"><b class="${(cap?.shortfall_seats ?? 0) > 0 ? 'bad' : 'good'}">${cap?.shortfall_seats ?? 0}</b><span>seats short</span></div>
        <div class="metric"><b>${cap?.registered_judges ?? 0}</b><span>judges (${cap?.unrestricted_judges ?? 0} unrestricted)</span></div>
        <div class="metric"><b>${cap?.waiting_more ?? 0}</b><span>waiting for another group</span></div>
        <div class="metric"><b>${cap?.paused_judges ?? 0}</b><span>paused</span></div>
        <div class="metric"><b>${st?.complete_groups ?? 0} / ${st?.total_groups ?? 0}</b><span>groups complete</span></div>
        <div class="metric"><b>${st?.total_reviews ?? 0}</b><span>reviews (${st?.total_skips ?? 0} skipped, ${st?.total_dnfs ?? 0} did not finish)</span></div>
        ${eligible.length ? `<div class="metric"><b>${Math.min(...eligible)} / ${median(eligible)}</b><span>eligible judges per group, min / median</span></div>` : ''}
      </div>
      ${noEligible.length ? `<div class="alert alert-warning"><b>${noEligible.length} judge${noEligible.length === 1 ? '' : 's'} cannot be seated on any group</b> (their blocklist or their own stories rule every group out). Ask them to loosen the blocklist: ${noEligible.map((j) => esc(j.display_name)).join(', ')}.</div>` : ''}
      <div class="section"><h3>Groups</h3>${this.groupsTable(ctx, target)}</div>
      <div class="section"><h3>Judges</h3>${this.judgesTable(ctx)}</div>
      <div class="section"><h3>Seats</h3>${this.seatsTable(ctx)}</div>`;
  }

  private groupsTable(ctx: AdminContext, target: number): string {
    if (!this.groups.length) return '<div class="empty">No groups yet. Draft them on the “Round setup” tab.</div>';
    const open = this.judges.filter((j) => j.accepted_at).map((j) => `<option value="${esc(j.user_id)}">#${esc(j.judge_number ?? '?')} ${esc(j.display_name)}</option>`).join('');
    return `<div class="table-wrap"><table><thead><tr><th>Group</th><th>Status</th><th>Warnings</th><th class="num">Seats</th><th class="num">Eligible judges</th><th class="num">Reviews per story</th><th>Actions</th></tr></thead><tbody>
      ${this.groups.map((g) => {
        const r = this.results.get(g.group_id);
        const counts = r?.stories.map((s) => s.submitted_count) ?? [];
        const el = this.preview.get(g.group_id)?.eligible_judges_count;
        const canSeat = g.status === 'open' || g.status === 'complete';
        return `<tr><td><b>${g.number}</b></td><td><span class="badge ${g.status === 'complete' ? 'badge-success' : g.status === 'open' ? 'badge-info' : ''}">${esc(g.status)}</span></td>
          <td>${triggerTags(g.trigger_slugs, ctx.triggers)}</td>
          <td class="num ${g.seats < target ? 'bad' : 'good'}">${g.seats} / ${target}</td><td class="num ${el !== undefined && el < target ? 'bad' : ''}">${el ?? ''}</td>
          <td class="num">${counts.length ? `${Math.min(...counts)}–${Math.max(...counts)} (min ${ctx.round!.min_reviews_per_story})` : ''}</td>
          <td>${canSeat ? `<div class="row"><select aria-label="Judge" data-judge-for="${esc(g.group_id)}"><option value="">Seat a judge…</option>${open}</select><button type="button" class="btn btn-secondary btn-sm" data-action="assign-seat" data-group="${esc(g.group_id)}" ${ctx.busy ? 'disabled' : ''}>Seat</button>
            ${g.status === 'open' ? `<button type="button" class="btn btn-secondary btn-sm" data-action="force-complete" data-group="${esc(g.group_id)}" ${ctx.busy ? 'disabled' : ''}>Mark complete</button>` : ''}</div>` : ''}</td></tr>`;
      }).join('')}</tbody></table></div>`;
  }

  private judgesTable(ctx: AdminContext): string {
    if (!this.judges.length) return '<div class="empty">No judges have registered yet.</div>';
    return `<div class="table-wrap"><table><thead><tr><th class="num">#</th><th>Judge</th><th class="num">Blocks</th><th>Reviewing</th><th class="num">Bonus</th><th class="num">Held</th><th class="num">Done</th><th class="num">Left</th><th class="num">Reviews</th><th class="num">Skipped</th><th class="num">DNF</th><th class="num">Could still take</th></tr></thead><tbody>
      ${this.judges.map((j) => `<tr><td class="num">${esc(j.judge_number ?? '')}</td><td>${esc(j.display_name)}${j.accepted_at ? '' : ' <span class="badge badge-info" title="Invited; not seated until they accept">invited</span>'}${j.waiting_since ? ` <span class="badge badge-warning" title="since ${esc(fmtDateTime(j.waiting_since))}">waiting for more</span>` : ''}</td>
        <td class="num" title="${esc((j.blocked_triggers ?? []).join(', '))}">${j.blocked_count ?? 0}</td>
        <td>${j.intake === 'paused' ? `<span class="badge badge-warning">paused${j.pause_reason ? `: ${esc(j.pause_reason)}` : ''}</span>` : 'active'}</td>
        <td class="num"><button type="button" class="btn btn-secondary btn-sm" data-action="bonus" data-judge="${esc(j.user_id)}" data-bonus="${j.bonus_groups - 1}" ${j.bonus_groups <= 0 || ctx.busy ? 'disabled' : ''} aria-label="Take back a bonus group">−</button>
          ${j.bonus_groups} <button type="button" class="btn btn-secondary btn-sm" data-action="bonus" data-judge="${esc(j.user_id)}" data-bonus="${j.bonus_groups + 1}" ${ctx.busy ? 'disabled' : ''} aria-label="Grant a bonus group">+</button></td>
        <td class="num">${j.groups_held}</td><td class="num">${j.groups_completed}</td><td class="num">${j.groups_left}</td><td class="num">${j.submitted_count}</td><td class="num">${j.skipped_count}</td><td class="num">${j.dnf_count}</td>
        <td class="num ${j.eligible_groups === 0 && j.accepted_at ? 'bad' : ''}">${j.eligible_groups}</td></tr>`).join('')}</tbody></table></div>`;
  }

  private seatsTable(ctx: AdminContext): string {
    if (!this.seats.length) return '<div class="empty">No seats yet.</div>';
    const idleDays = ctx.round!.reminder_after_days;
    return `<div class="table-wrap"><table><thead><tr><th>Group</th><th>Judge</th><th>Status</th><th>Source</th><th class="num">Progress</th><th>Since</th><th></th></tr></thead><tbody>
      ${this.seats.map((s) => {
        const total = s.assigned_count + s.submitted_count + s.skipped_count + s.dnf_count;
        const age = (Date.now() - Date.parse(s.assigned_at)) / 86_400_000;
        const idle = s.status === 'assigned' && !s.first_opened_at && age >= idleDays;
        return `<tr><td>${s.group_number}</td><td>${esc(s.judge_name)}</td>
          <td>${esc(s.status)}${s.release_reason ? ` (${esc(s.release_reason)})` : ''}${s.left_reason ? ` (${esc(s.left_reason)})` : ''}${idle ? ` <span class="badge badge-warning">not opened for ${Math.floor(age)} days</span>` : ''}</td>
          <td>${esc(s.source)}</td><td class="num">${s.submitted_count + s.skipped_count + s.dnf_count} / ${total}</td><td>${esc(fmtDateTime(s.assigned_at))}</td>
          <td>${s.status === 'assigned' ? `<div class="row"><button type="button" class="btn btn-secondary btn-sm" data-action="nudge" data-judge="${esc(s.judge_id)}" title="Queue a reminder email" ${ctx.busy ? 'disabled' : ''}>Nudge</button>
            <button type="button" class="btn btn-danger btn-sm" data-action="release-seat" data-seat="${esc(s.seat_id)}" ${ctx.busy ? 'disabled' : ''}>Release</button></div>` : ''}</td></tr>`;
      }).join('')}</tbody></table></div>`;
  }

  async onAction(name: string, el: HTMLElement, ctx: AdminContext) {
    switch (name) {
      case 'assign-seat': {
        const groupId = el.getAttribute('data-group') ?? '';
        const judge = (el.parentElement?.querySelector('select') as HTMLSelectElement | null)?.value;
        if (!judge) return ctx.flash('error', 'Choose the judge to seat.');
        return ctx.run(async () => {
          await assignSeat(groupId, judge);
          return 'Judge seated.';
        });
      }
      case 'force-complete':
        if (!confirm('Mark this group complete? It will count as done even if some stories have fewer reviews than the minimum.')) return;
        return ctx.run(async () => {
          await forceCompleteGroup(el.getAttribute('data-group') ?? '');
          return 'Group marked complete.';
        });
      case 'release-seat':
        if (!confirm('Release this seat? The stories the judge has not reviewed go back to the pool; their submitted reviews stay.')) return;
        return ctx.run(async () => {
          await releaseSeat(el.getAttribute('data-seat') ?? '', null);
          return 'Seat released.';
        });
      case 'nudge': {
        const judge = el.getAttribute('data-judge') ?? '';
        return ctx.run(async () => {
          const r = await nudgeJudge(ctx.round!.id, judge);
          return r.queued ? 'A reminder is queued. Send the queued emails on the Emails tab.' : 'A reminder was already queued for this seat today.';
        });
      }
      case 'bonus':
        return ctx.run(async () => {
          await setBonusGroups(ctx.round!.id, el.getAttribute('data-judge') ?? '', Number(el.getAttribute('data-bonus')));
        });
    }
  }
}
