/**
 * The "Results" tab: who won each group, how solid the call is, and the admin's decision about who advances.
 * Nothing advances by itself. The system proposes each group's winner and, where the call is close, the runner-up as a
 * wildcard candidate (strongest first); the admin confirms or unconfirms. Two CSV exports: every review with its
 * answers, and the group results.
 */
import { adminExport, groupResults, proposals, questionForm, setAdvancement } from '../api';
import { downloadCsv, groupResultsCsv, reviewsCsv } from '../csv';
import type { CloseCallReason, GroupResult, Proposal, QuestionForm } from '../types';
import { esc, fmtDateTime, type AdminContext, type AdminTab } from './context';

export const REASON_TEXT: Record<CloseCallReason, string> = {
  tie: 'the top two are tied',
  second_has_more_positive_recommendations: 'second place has more positive recommendations',
  raw_mean_differs: 'the plain average (no centering) picks a different winner',
};

const pct = (p: number | null | undefined): string => (p === null || p === undefined ? '–' : `${Math.round(p * 100)}%`);
const score = (n: number | null | undefined): string => (n === null || n === undefined ? '–' : n.toFixed(2));

export class ResultsTab implements AdminTab {
  id = 'results';
  label = 'Results';

  private results: GroupResult[] = [];
  private proposed: Proposal[] = [];
  private form: QuestionForm | null = null;

  async load(ctx: AdminContext) {
    this.results = [];
    this.proposed = [];
    this.form = null;
    if (!ctx.round) return;
    [this.results, this.proposed, this.form] = await Promise.all([groupResults(ctx.round.id), proposals(ctx.round.id), questionForm(ctx.round.id)]);
  }

  render(ctx: AdminContext): string {
    if (!ctx.round) return '<div class="empty">Create the round on the “Round setup” tab first.</div>';
    const scored = this.results.filter((g) => g.scored_stories > 0);
    const close = scored.filter((g) => g.close_call);
    const advancing = this.results.flatMap((g) => g.stories).filter((s) => s.advances).length;
    const canAdvance = ctx.round.status === 'reviewing' || ctx.round.status === 'closed';
    const winners = this.proposed.filter((p) => p.kind === 'winner');
    const wild = this.proposed.filter((p) => p.kind === 'wildcard_candidate');
    return `
      <div class="metrics">
        <div class="metric"><b>${scored.length} / ${this.results.length}</b><span>groups with a result</span></div>
        <div class="metric"><b>${close.length}</b><span>close calls</span></div>
        <div class="metric"><b>${wild.length}</b><span>wildcard candidates</span></div>
        <div class="metric"><b class="${advancing ? 'good' : ''}">${advancing}</b><span>stories confirmed to advance</span></div>
      </div>
      <div class="row" style="margin-bottom: 1.25rem;">
        <button type="button" class="btn btn-secondary" data-action="export-reviews" ${ctx.busy ? 'disabled' : ''}>Download reviews (CSV)</button>
        <button type="button" class="btn btn-secondary" data-action="export-results" ${ctx.busy || !this.results.length ? 'disabled' : ''}>Download group results (CSV)</button>
        <span class="muted">Judge number and name only, no emails. Titles and names that look like formulas are made safe for spreadsheets.</span>
      </div>
      ${this.form?.scoring_changed_after_advancement ? `<div class="alert alert-warning"><b>The scoring changed after ${esc(this.form.advancing_count)} ${this.form.advancing_count === 1 ? 'advancement was' : 'advancements were'} confirmed.</b> A weight, the recommendations that count as positive, or a scored question was changed (${esc(fmtDateTime(this.form.scoring_changed_at))}). The scores and proposals below use the current form; the confirmed advancements stay as you set them. Look at the proposal again and confirm again if you want it to follow.</div>` : ''}
      ${canAdvance ? '' : '<div class="alert alert-info">Advancement can be set once reviewing has started.</div>'}
      ${scored.length === 0 ? '<div class="empty">No story has a score yet. Scores need at least two reviews from a judge in the same group.</div>' : `
        <div class="section"><h3>Wildcard candidates, strongest first (${wild.length})</h3>
          <p class="muted">The runner-up of a close call. The strongest have the larger share of positive recommendations, then the smaller margin behind their group's winner.</p>
          ${wild.length ? this.proposalTable(ctx, wild, canAdvance) : '<div class="empty">None: no group is a close call.</div>'}</div>
        <div class="section"><h3>Group winners (${winners.length})</h3>
          <div class="row" style="margin-bottom:0.75rem;"><button type="button" class="btn btn-success btn-sm" data-action="confirm-clear-winners" ${ctx.busy || !canAdvance ? 'disabled' : ''}>Confirm all winners that are not close calls</button>
          <span class="muted">Close calls stay for you to decide.</span></div>
          ${this.proposalTable(ctx, winners, canAdvance)}</div>
        <div class="section"><h3>All groups</h3>${this.results.map((g) => this.groupCard(ctx, g, canAdvance)).join('')}</div>`}`;
  }

  private proposalTable(ctx: AdminContext, rows: Proposal[], canAdvance: boolean): string {
    return `<div class="table-wrap"><table><thead><tr><th class="num">Group</th><th>Story</th><th class="num">Positive recommendations</th><th class="num">Margin behind winner / ahead of second</th><th>Why</th><th></th></tr></thead><tbody>
      ${rows.map((p) => `<tr><td class="num">${p.group_number}</td><td><b>${esc(p.story_title)}</b></td>
        <td class="num">${p.positive_recommendations} of ${p.recommendations} (${pct(p.positive_share)})</td><td class="num">${score(p.margin)}</td>
        <td>${p.close_call ? p.close_call_reasons.map((r) => esc(REASON_TEXT[r] ?? r)).join('; ') : '<span class="muted">clear winner</span>'}</td>
        <td>${this.advanceButton(ctx, p.story_id, p.currently_advances, p.kind === 'winner' ? 'winner' : 'wildcard', canAdvance)}</td></tr>`).join('')}
    </tbody></table></div>`;
  }

  private advanceButton(ctx: AdminContext, storyId: string, advances: boolean, note: string, canAdvance: boolean): string {
    return advances
      ? `<button type="button" class="btn btn-danger btn-sm" data-action="unconfirm" data-story="${esc(storyId)}" ${ctx.busy || !canAdvance ? 'disabled' : ''}>Unconfirm</button> <span class="badge badge-success">advances</span>`
      : `<button type="button" class="btn btn-success btn-sm" data-action="confirm" data-story="${esc(storyId)}" data-note="${esc(note)}" ${ctx.busy || !canAdvance ? 'disabled' : ''}>Confirm</button>`;
  }

  private groupCard(ctx: AdminContext, g: GroupResult, canAdvance: boolean): string {
    return `<div class="group-card"><header>
        <div><b>Group ${g.group_number}</b> <span class="badge ${g.group_status === 'complete' ? 'badge-success' : ''}">${esc(g.group_status)}</span>
          ${g.close_call ? '<span class="badge badge-warning">close call</span>' : g.scored_stories > 1 ? '<span class="badge badge-success">clear</span>' : ''}</div>
        <div class="muted">${g.margin !== null ? `margin ${score(g.margin)}` : ''}</div></header>
      ${g.close_call ? `<div class="story muted">${g.close_call_reasons.map((r) => esc(REASON_TEXT[r] ?? r)).join('; ')}</div>` : ''}
      <div class="table-wrap"><table><thead><tr><th class="num">Rank</th><th>Story</th><th class="num">Score</th><th class="num">Plain avg</th><th class="num">Scored</th><th class="num">Reviews</th><th class="num">DNF</th><th class="num">Skipped</th><th class="num">Positive</th><th></th></tr></thead><tbody>
        ${g.stories.map((s) => `<tr><td class="num">${s.rank ?? '–'}</td><td>${esc(s.title)}${s.meets_min_reviews ? '' : ' <span class="badge badge-warning">too few reviews</span>'}</td>
          <td class="num">${score(s.weighted_score)}</td><td class="num">${score(s.raw_score)}</td><td class="num">${s.review_count}</td><td class="num">${s.submitted_count}</td><td class="num">${s.dnf_count}</td><td class="num">${s.skip_count}</td>
          <td class="num">${s.positive_recommendations}/${s.recommendations} (${pct(s.positive_share)})</td>
          <td>${this.advanceButton(ctx, s.story_id, s.advances, 'manual', canAdvance)}</td></tr>`).join('')}
      </tbody></table></div></div>`;
  }

  async onAction(name: string, el: HTMLElement, ctx: AdminContext) {
    const story = el.getAttribute('data-story') ?? '';
    switch (name) {
      case 'confirm':
        return ctx.run(async () => {
          await setAdvancement(ctx.round!.id, [story], true, el.getAttribute('data-note'));
        });
      case 'unconfirm':
        return ctx.run(async () => {
          await setAdvancement(ctx.round!.id, [story], false, null);
        });
      case 'confirm-clear-winners': {
        const ids = this.proposed.filter((p) => p.kind === 'winner' && !p.close_call && !p.currently_advances).map((p) => p.story_id);
        if (!ids.length) return ctx.flash('info', 'Every clear winner is already confirmed.');
        if (!confirm(`Confirm ${ids.length} clear winners as advancing?`)) return;
        return ctx.run(async () => {
          await setAdvancement(ctx.round!.id, ids, true, 'winner');
          return `${ids.length} winners confirmed.`;
        });
      }
      case 'export-reviews':
        return ctx.run(async () => {
          const rows = await adminExport(ctx.round!.id);
          downloadCsv(`round-${ctx.round!.number}-reviews-${new Date().toISOString().slice(0, 10)}.csv`, reviewsCsv(rows, ctx.questions));
          return `Downloaded ${rows.length} reviews.`;
        });
      case 'export-results':
        downloadCsv(`round-${ctx.round!.number}-group-results-${new Date().toISOString().slice(0, 10)}.csv`, groupResultsCsv(this.results));
        return;
    }
  }
}
