/**
 * Typed calls to the story-review RPCs, and one place that turns a database or network error into a message a
 * person can act on. Every function returns data or throws an Error whose message is safe to show (the views run it
 * through escapeHtml before putting it in the page).
 */
import { getSupabaseClient } from '../common/supabase-client';
import type {
  AdminGroup, AdminJudge, AdminSeat, AdminTrigger, BlocklistResult, DnfReason, ExportRow, FoundUser, GroupResult, JudgeCandidate, OutboxSummary, PreviewGroup, Proposal, QuestionChange, QuestionForm, SkipReason, TriggerChange, Unregistration,
} from './types';

const MESSAGES: [RegExp, string][] = [
  [/jwt expired|invalid jwt|not authenticated|authentication required/i, 'Your session has expired. Please sign in again.'],
  [/failed to fetch|networkerror|load failed/i, 'Could not reach the server. Check your connection and try again.'],
  [/permission denied|row-level security|violates row-level/i, 'You do not have permission to do that.'],
  [/duplicate key/i, 'That already exists.'],
];

/** The text to show for an error from the database, the network or the code. */
export function friendlyError(err: unknown, fallback = 'Something went wrong. Please try again.'): string {
  const raw = typeof err === 'string' ? err : err && typeof err === 'object' && 'message' in err ? String((err as { message: unknown }).message) : '';
  if (!raw) return fallback;
  for (const [re, text] of MESSAGES) if (re.test(raw)) return text;
  return raw;
}

/** Calls a database function; throws Error(friendlyError(...)) on failure. */
export async function rpc<T>(name: string, args: Record<string, unknown> = {}): Promise<T> {
  const { data, error } = await getSupabaseClient().rpc(name, args);
  if (error) throw new Error(friendlyError(error));
  return data as T;
}

