/**
 * Sends the queued emails now: calls the send-emails function with the signed-in administrator's own session (the
 * function checks with the database that they are an admin). It sends at most `limit` messages per call.
 */
export async function sendQueuedEmails(limit = 50): Promise<{ claimed: number; sent: number; failed: number }> {
  const { data, error } = await getSupabaseClient().functions.invoke('send-emails', { body: { limit } });
  if (error) {
    const status = (error as { context?: { status?: number } }).context?.status;
    if (status === 401) throw new Error('Only an administrator can send the emails. Sign in again and retry.');
    if (status === 500) throw new Error('The sending failed. The email settings may be missing or wrong: see docs/email-setup.md, and look at the function logs.');
    throw new Error(friendlyError(error, 'The emails could not be sent. Check that the send-emails function is deployed.'));
  }
  return data as { claimed: number; sent: number; failed: number };
}

