// <rg-sign-in-prompt>: what a page that needs a signed-in person shows to someone signed out. It has no form of its
// own: both buttons open the site-wide sign-in dialog (the same one as the header button), on the right tab.
// Attributes: heading, message (plain text, escaped).
import { escapeHtml } from '../common/sanitize';

const css = `
:host {
  display: block; max-width: 420px; margin: 2rem auto; box-sizing: border-box; color: #1a1a1a;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}
*, *::before, *::after { box-sizing: border-box; }
.card {
  background: #fff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 2rem; text-align: center;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, .05), 0 2px 4px -1px rgba(0, 0, 0, .03);
}
h2 { font-size: 1.35rem; font-weight: 700; margin: 0 0 .5rem; color: #0f172a; }
p { font-size: .95rem; line-height: 1.5; color: #475569; margin: 0 0 1.5rem; }
.actions { display: flex; flex-direction: column; gap: .6rem; }
button {
  width: 100%; padding: .75rem; border-radius: 6px; font: inherit; font-size: .95rem; font-weight: 600; cursor: pointer;
  transition: background-color .15s ease;
}
.primary { background: #0284c7; color: #fff; border: none; }
.primary:hover { background: #0369a1; }
.secondary { background: #fff; color: #0284c7; border: 1px solid #cbd5e1; }
.secondary:hover { background: #f1f5f9; }
`;

export class RgSignInPrompt extends HTMLElement {
  static observedAttributes = ['heading', 'message'];
  private root = this.attachShadow({ mode: 'open' });

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.isConnected) this.render();
  }

  private render() {
    const heading = this.getAttribute('heading') || 'Sign in to continue';
    const message = this.getAttribute('message') || 'Sign in to your Real Good AI account, or create one. It only takes a minute.';
    this.root.innerHTML = `<style>${css}</style>
      <div class="card">
        <h2>${escapeHtml(heading)}</h2>
        <p>${escapeHtml(message)}</p>
        <div class="actions">
          <button type="button" class="primary" data-mode="login">Sign in</button>
          <button type="button" class="secondary" data-mode="signup">Create an account</button>
        </div>
      </div>`;
    this.root.querySelectorAll<HTMLButtonElement>('button[data-mode]').forEach((b) =>
      b.addEventListener('click', async () => {
        const { openAuthDialog } = await import('./account-dialog');
        openAuthDialog(b.dataset.mode === 'signup' ? 'signup' : 'login');
      }),
    );
  }
}

if (!customElements.get('rg-sign-in-prompt')) {
  customElements.define('rg-sign-in-prompt', RgSignInPrompt);
}
