/**
 * The "Round setup" tab: the event and round settings, the review form, and the steps that take a round from
 * "stories coming in" to "judges are reading": close submissions, draft and adjust the groups, seat the first pass.
 */
import { getSupabaseClient } from '../../common/supabase-client';
import {
  adminGroups, closeRound, closeSubmissions, confirmGroups, createNextRound, draftGroups, groupResults, moveStory, previewGroups, proposeFirstPass,
  releaseFirstPass, seedQuestions,
} from '../api';
import type { AdminGroup, PreviewGroup } from '../types';
import { QuestionEditor } from './question-editor';
import { esc, fromLocalInput, isSafeImageUrl, toLocalInput, triggerTags, type AdminContext, type AdminTab } from './context';

const val = (root: ParentNode, id: string): string => (root.querySelector<HTMLInputElement>(`#${id}`)?.value ?? '').trim();
const num = (root: ParentNode, id: string): number => Number(val(root, id));

export class SetupTab implements AdminTab {
  id = 'setup';
  label = 'Round setup';

  private groups: AdminGroup[] = [];
  private preview = new Map<string, PreviewGroup>();
  private proposed: number | null = null;
  private method: 'trigger_aware' | 'random' = 'trigger_aware';
  /** Stories confirmed to advance out of this round (once it is reviewing or closed), and into it (round 2 onward). */
  private advancingOut = 0;
  private advancingIn = 0;
  private editor = new QuestionEditor();

  async load(ctx: AdminContext) {
    await this.editor.load(ctx);
    this.groups = [];
    this.preview.clear();
    this.advancingOut = 0;
    this.advancingIn = 0;
    const status = ctx.round?.status;
    const countAdvancing = async (roundId: string) => (await groupResults(roundId)).flatMap((g) => g.stories).filter((s) => s.advances).length;
    if (ctx.round && (status === 'reviewing' || status === 'closed')) this.advancingOut = await countAdvancing(ctx.round.id);
    const before = ctx.round ? ctx.rounds.find((r) => r.number === ctx.round!.number - 1) : undefined;
    if (before) this.advancingIn = await countAdvancing(before.id);
    if (ctx.round && (status === 'grouping' || status === 'assigning')) {
      this.groups = await adminGroups(ctx.round.id);
      const p = await previewGroups(ctx.round.id);
      for (const g of p.groups ?? []) this.preview.set(g.group_id, g);
    }
  }

  render(ctx: AdminContext): string {
    return `${this.eventSection(ctx)}${this.roundSection(ctx)}${ctx.round ? this.formSection(ctx) + this.stepsSection(ctx) + this.nextRoundSection(ctx) : ''}`;
  }

  // ── event ────────────────────────────────────────────────────────────────────────────────────
  private eventSection(ctx: AdminContext): string {
    const ev = ctx.event;
    return `
      <div class="section">
        <h3>Event</h3>
        <div class="row" style="margin-bottom: 1rem;">
          ${ctx.events.length > 1 ? `<div class="field"><label for="ev-pick">Event</label><select id="ev-pick" data-action="pick-event">${ctx.events.map((e) => `<option value="${esc(e.id)}" ${e.id === ev?.id ? 'selected' : ''}>${esc(e.title)} (${esc(e.status)})</option>`).join('')}</select></div>` : ''}
          <button type="button" class="btn btn-secondary btn-sm" data-action="new-event">+ New event</button>
        </div>
        ${ev ? `
        <div class="form-grid">
          <div class="field"><label for="ev-title">Title</label><input id="ev-title" maxlength="150" value="${esc(ev.title)}" /></div>
          <div class="field"><label for="ev-status">Status</label>
            <select id="ev-status">${(['draft', 'open', 'archived'] as const).map((s) => `<option value="${s}" ${ev.status === s ? 'selected' : ''}>${s}</option>`).join('')}</select>
            <div class="hint">Judges and authors only see an <b>open</b> event.</div></div>
          <div class="field"><label for="ev-deadline">Submissions close at</label><input id="ev-deadline" type="datetime-local" value="${esc(toLocalInput(ev.submissions_close_at))}" />
            <div class="hint">After this time authors can no longer write or edit. Leave empty to close by hand.</div></div>
          <div class="field"><label for="ev-image">Image URL (https)</label><input id="ev-image" value="${esc(ev.image_url ?? '')}" placeholder="https://…" />
            ${ev.image_url && isSafeImageUrl(ev.image_url) ? `<img class="event-img" src="${esc(ev.image_url)}" alt="" referrerpolicy="no-referrer" loading="lazy" />` : ''}</div>
          <div class="field" style="grid-column: 1 / -1;"><label for="ev-desc">Description</label><textarea id="ev-desc" rows="3">${esc(ev.description ?? '')}</textarea></div>
        </div>
        <div class="row" style="margin-top: 1rem;"><button type="button" class="btn btn-primary" data-action="save-event" ${ctx.busy ? 'disabled' : ''}>Save event</button>
        ${ev.submissions_closed ? '<span class="badge badge-warning">Submissions closed</span>' : ''}</div>` : '<div class="empty">No event yet. Create one to get started.</div>'}
      </div>`;
  }

  // ── round ────────────────────────────────────────────────────────────────────────────────────
  private roundSection(ctx: AdminContext): string {
    if (!ctx.event) return '';
    const r = ctx.round;
    if (!r) {
      return `<div class="section"><h3>Round 1</h3><p class="muted">This event has no round yet.</p><button type="button" class="btn btn-primary" data-action="create-round" ${ctx.busy ? 'disabled' : ''}>Create round 1</button></div>`;
    }
    const editable = r.status === 'planned' || r.status === 'grouping';
    const f = (id: string, label: string, v: number | string, hint = '') => `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="number" min="1" value="${esc(v)}" ${editable ? '' : 'disabled'} />${hint ? `<div class="hint">${hint}</div>` : ''}</div>`;
    return `
      <div class="section">
        <div class="step-head"><h3 style="margin:0;">${esc(r.name)}</h3><span class="badge badge-info">${esc(r.status)}</span></div>
        <div class="form-grid">
          <div class="field"><label for="rd-name">Name</label><input id="rd-name" value="${esc(r.name)}" ${editable ? '' : 'disabled'} /></div>
          ${f('rd-group-size', 'Stories per group', r.group_size, r.number === 1 ? '2 to 20; last year 5.' : '2 to 20; the default for a later round is 10.')}
          ${f('rd-target', 'Judges per group (target)', r.target_judges_per_group)}
          ${f('rd-min', 'Reviews per story (minimum)', r.min_reviews_per_story, 'A group is “complete” at this many.')}
          ${f('rd-per-judge', 'Groups per judge at first', r.groups_per_judge)}
          ${f('rd-throttle', 'New judges per group per day', r.max_new_judges_per_group_per_day, 'Spreads top-ups out.')}
          <div class="field"><label for="rd-due">Reviews due by</label><input id="rd-due" type="datetime-local" value="${esc(toLocalInput(r.review_due_at))}" ${editable ? '' : 'disabled'} /></div>
        </div>
        ${editable ? `<div class="row" style="margin-top:1rem;"><button type="button" class="btn btn-primary" data-action="save-round" ${ctx.busy ? 'disabled' : ''}>Save round settings</button></div>` : '<p class="muted" style="margin-bottom:0;">Settings are locked once the groups are confirmed.</p>'}
      </div>`;
  }

  private formSection(ctx: AdminContext): string {
    return this.editor.render(ctx);
  }

  // ── steps ────────────────────────────────────────────────────────────────────────────────────
  private stepsSection(ctx: AdminContext): string {
    const r = ctx.round!;
    const ev = ctx.event!;
    const st = ctx.dashboard?.stats;
    const cap = ctx.dashboard?.capacity;
    const closed = ev.submissions_closed;
    const status = r.status;
    const grouped = status === 'assigning' || status === 'reviewing' || status === 'closed';
    const reviewing = status === 'reviewing' || status === 'closed';
    const hasQuestions = ctx.questions.some((q) => !q.archived);
    const num = (n: number, ok: boolean, now: boolean) => `<span class="step-num ${ok ? 'ok' : now ? 'now' : ''}">${ok ? '✓' : n}</span>`;

    const later = r.number > 1;
    const step1 = later ? `
      <div class="section done">
        <div class="step-head">${num(1, true, false)}<h3 style="margin:0;">The stories</h3></div>
        <p class="muted" style="margin-bottom:0;">${this.advancingIn} ${this.advancingIn === 1 ? 'story' : 'stories'} advanced from round ${r.number - 1}. They are read again, in new sets, by the judges you invite to this round.</p>
      </div>` : `
      <div class="section ${closed ? 'done' : ''}">
        <div class="step-head">${num(1, closed, !closed)}<h3 style="margin:0;">Close submissions</h3></div>
        <p class="muted">${st ? `${st.submitted_stories} submitted stories (${st.total_stories - st.submitted_stories} drafts or withdrawn).` : ''}
          ${closed ? 'Submissions are closed and the submitted stories are locked.' : 'Closing locks every submitted story: authors can no longer edit or withdraw. Drafting the groups does this too.'}</p>
        ${closed ? '' : `<button type="button" class="btn btn-secondary" data-action="close-submissions" ${ctx.busy ? 'disabled' : ''}>Close submissions &amp; lock stories</button>`}
      </div>`;

    const canDraft = status === 'planned' || status === 'grouping';
    const step2 = `
      <div class="section ${grouped ? 'done' : ''}">
        <div class="step-head">${num(2, grouped, canDraft)}<h3 style="margin:0;">Group the stories</h3></div>
        <p class="muted">${cap ? `${cap.registered_judges} ${later ? 'judges accepted this round' : 'judges registered'} (${cap.unrestricted_judges} with no blocklist). ` : ''}Stories with the same content warnings are put together so that more judges can read each group.${later ? ' Invite the judges on the Judges tab first: only those who accepted are counted and seated. A judge never gets a story they already read in an earlier round.' : ''}</p>
        ${canDraft ? `
          <div class="row">
            <div class="field"><label for="draft-method">Method</label><select id="draft-method" data-action="pick-method"><option value="trigger_aware" ${this.method === 'trigger_aware' ? 'selected' : ''}>Cluster by content warnings (recommended)</option><option value="random" ${this.method === 'random' ? 'selected' : ''}>Random (for comparison)</option></select></div>
            <button type="button" class="btn btn-primary" data-action="draft-groups" ${ctx.busy || !hasQuestions ? 'disabled' : ''} style="align-self:flex-end;">${status === 'grouping' ? 'Draft again' : 'Draft groups'}</button>
          </div>
          ${hasQuestions ? '' : '<p class="bad">Add the review form first.</p>'}` : ''}
        ${(status === 'grouping' || status === 'assigning') ? this.groupsHtml(ctx, status === 'grouping') : ''}
        ${status === 'grouping' ? `<div class="row" style="margin-top:1rem;"><button type="button" class="btn btn-success" data-action="confirm-groups" ${ctx.busy ? 'disabled' : ''}>Confirm these groups</button><span class="muted">Moving stories is no longer possible after this.</span></div>` : ''}
      </div>`;

    const step3 = `
      <div class="section ${reviewing ? 'done' : ''}">
        <div class="step-head">${num(3, reviewing, status === 'assigning')}<h3 style="margin:0;">Seat the first judges and start reviewing</h3></div>
        ${status === 'assigning' ? `
          <p class="muted">Propose seats first and look at the numbers (the Capacity tab shows who sits where). Nobody sees a seat until you release.</p>
          <div class="row"><button type="button" class="btn btn-secondary" data-action="propose-seats" ${ctx.busy ? 'disabled' : ''}>Propose seats</button>
          ${this.proposed !== null ? `<span class="good">${this.proposed} seats proposed.</span>` : ''}
          <button type="button" class="btn btn-success" data-action="release-seats" ${ctx.busy ? 'disabled' : ''}>Release seats &amp; start reviewing</button></div>`
          : reviewing ? `<p class="good">Reviewing ${status === 'closed' ? 'is closed.' : 'is under way.'} See the Capacity and Results tabs.</p>`
          : '<p class="muted">Available once the groups are confirmed.</p>'}
      </div>`;
    return step1 + step2 + step3;
  }

  // ── the next round ───────────────────────────────────────────────────────────────────────────
  private nextRoundSection(ctx: AdminContext): string {
    const r = ctx.round!;
    const isLatest = ctx.rounds[ctx.rounds.length - 1]?.id === r.id;
    if (!isLatest || (r.status !== 'reviewing' && r.status !== 'closed')) return '';
    const n = r.number + 1;
    const close = r.status === 'reviewing'
      ? `<p class="muted">Closing the round stops reviewing: nobody can submit, skip, leave or be seated any more. Do it when the results are in.</p>
         <button type="button" class="btn btn-secondary" data-action="close-round" ${ctx.busy ? 'disabled' : ''}>Close ${esc(r.name)}</button>`
      : '<p class="good" style="margin-top:0;">This round is closed.</p>';
    const create = this.advancingOut > 0
      ? `<p class="muted">${this.advancingOut} ${this.advancingOut === 1 ? 'story is' : 'stories are'} confirmed to advance. Round ${n} starts with sets of 10 stories, 4 judges per set and at least 3 reviews per story, and the same review form; you can change all of these before drafting.</p>
         <button type="button" class="btn btn-primary" data-action="create-next-round" ${ctx.busy ? 'disabled' : ''}>Create round ${n}</button>`
      : `<p class="muted">Confirm which stories advance on the Results tab first; round ${n} is made from them.</p>`;
    return `
      <div class="section">
        <h3>Next round</h3>
        ${close}
        <div style="margin-top: 1rem;">${create}</div>
      </div>`;
  }

  private groupsHtml(ctx: AdminContext, movable: boolean): string {
    if (!this.groups.length) return '<div class="empty">No groups yet.</div>';
    const target = ctx.round!.target_judges_per_group;
    return `<div style="margin-top: 1rem;">${this.groups.map((g) => {
      const p = this.preview.get(g.group_id);
      const eligible = p?.eligible_judges_count ?? 0;
      const short = eligible < target;
      return `<div class="group-card"><header>
          <div><b>Group ${g.number}</b> <span class="muted">· ${g.stories.length} stories · warnings:</span> ${triggerTags(g.trigger_slugs, ctx.triggers)}</div>
          <div class="${short ? 'bad' : 'good'}">${eligible} eligible judges${short ? ` (fewer than ${target})` : ''}</div></header>
        ${g.stories.map((s) => `<div class="story"><div><b>${esc(s.title)}</b> <span class="muted">by ${esc(s.author_name)}</span><div>${triggerTags(s.trigger_slugs, ctx.triggers)}</div></div>
          ${movable ? `<div class="row"><select aria-label="Move to group" data-move-for="${esc(s.story_id)}"><option value="">Move to…</option>${this.groups.filter((o) => o.group_id !== g.group_id).map((o) => `<option value="${esc(o.group_id)}">Group ${o.number}</option>`).join('')}</select>
            <button type="button" class="btn btn-secondary btn-sm" data-action="move-story" data-story="${esc(s.story_id)}" ${ctx.busy ? 'disabled' : ''}>Move</button></div>` : ''}</div>`).join('')}
      </div>`;
    }).join('')}</div>`;
  }

  // ── actions ──────────────────────────────────────────────────────────────────────────────────
  async onAction(name: string, el: HTMLElement, ctx: AdminContext, root: ParentNode) {
    if (await this.editor.onAction(name, el, ctx, root)) return;
    const sb = getSupabaseClient();
    switch (name) {
      case 'pick-event': {
        const id = (el as HTMLSelectElement).value;
        ctx.event = ctx.events.find((e) => e.id === id) ?? ctx.event;
        await ctx.reload();
        return;
      }
      case 'pick-method':
        this.method = (el as HTMLSelectElement).value === 'random' ? 'random' : 'trigger_aware';
        return;
      case 'new-event':
        return ctx.run(async () => {
          const { data, error } = await sb.from('events').insert({ title: 'New event', status: 'draft' }).select('*').single();
          if (error) throw error;
          ctx.events = [data, ...ctx.events];
          ctx.event = data;
          return 'Event created as a draft. Fill it in and save.';
        });
      case 'save-event': {
        // read the form first: ctx.run() re-renders the screen before it starts
        const form = { title: val(root, 'ev-title'), description: val(root, 'ev-desc'), image: val(root, 'ev-image'), status: val(root, 'ev-status'), deadline: val(root, 'ev-deadline') };
        return ctx.run(async () => {
          if (form.image && !isSafeImageUrl(form.image)) throw new Error('The image URL must start with https:// and contain no spaces.');
          if (!form.title) throw new Error('The event needs a title.');
          const { error } = await sb.from('events').update({
            title: form.title, description: form.description || null, image_url: form.image || null,
            status: form.status, submissions_close_at: fromLocalInput(form.deadline),
          }).eq('id', ctx.event!.id);
          if (error) throw error;
          return 'Event saved.';
        });
      }
      case 'create-round':
        return ctx.run(async () => {
          const { error } = await sb.from('rounds').insert({ event_id: ctx.event!.id, number: 1, name: 'Round 1' });
          if (error) throw error;
          return 'Round 1 created with the default settings.';
        });
      case 'save-round': {
        const form = {
          name: val(root, 'rd-name'), group_size: num(root, 'rd-group-size'), target: num(root, 'rd-target'), min: num(root, 'rd-min'),
          perJudge: num(root, 'rd-per-judge'), throttle: num(root, 'rd-throttle'), due: val(root, 'rd-due'),
        };
        return ctx.run(async () => {
          const { error } = await sb.from('rounds').update({
            name: form.name || ctx.round!.name, group_size: form.group_size, target_judges_per_group: form.target, min_reviews_per_story: form.min,
            groups_per_judge: form.perJudge, max_new_judges_per_group_per_day: form.throttle, review_due_at: fromLocalInput(form.due),
          }).eq('id', ctx.round!.id);
          if (error) throw error;
          return 'Round settings saved.';
        });
      }
      case 'close-round':
        if (!confirm(`Close ${ctx.round!.name}? Nobody will be able to submit, skip, leave or be seated in it any more.`)) return; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        return ctx.run(async () => {
          await closeRound(ctx.round!.id);
          return `${ctx.round!.name} is closed.`; // plain text (confirm box, flash or feedback message: escaped where it is shown)
        });
      case 'create-next-round':
        return ctx.run(async () => {
          const r = await createNextRound(ctx.round!.id);
          ctx.selectRound(r.number);
          return `Round ${r.number} created from ${r.advancing_stories} advancing stories. Check its settings, invite judges, then draft the groups.`;
        });
      case 'seed-questions':
        return ctx.run(async () => {
          const r = await seedQuestions(ctx.round!.id);
          return `Added ${r.questions} questions.`;
        });
      case 'close-submissions':
        if (!confirm('Close submissions and lock every submitted story? Authors will no longer be able to edit them.')) return;
        return ctx.run(async () => {
          const r = await closeSubmissions(ctx.event!.id);
          return `Submissions closed; ${r.newly_locked_stories} stories locked.`;
        });
      case 'draft-groups':
        return ctx.run(async () => {
          const r = (await draftGroups(ctx.round!.id, this.method)) as { total_groups: number; total_stories: number };
          return `Drafted ${r.total_groups} groups from ${r.total_stories} stories. Look them over, move stories if you want, then confirm.`;
        });
      case 'move-story': {
        const storyId = el.getAttribute('data-story') ?? '';
        const target = (el.parentElement?.querySelector('select') as HTMLSelectElement | null)?.value;
        if (!target) {
          ctx.flash('error', 'Choose the group to move the story to.');
          return;
        }
        return ctx.run(async () => {
          await moveStory(ctx.round!.id, storyId, target);
          return 'Story moved.';
        });
      }
      case 'confirm-groups':
        if (!confirm('Confirm the groups? After this, stories can no longer be moved between groups.')) return;
        return ctx.run(async () => {
          await confirmGroups(ctx.round!.id);
          return 'Groups confirmed. Now propose the first seats.';
        });
      case 'propose-seats':
        return ctx.run(async () => {
          const r = await proposeFirstPass(ctx.round!.id);
          this.proposed = r.seats_proposed;
        });
      case 'release-seats':
        if (!confirm('Release the seats and start reviewing? Judges can then see and read their stories.')) return;
        return ctx.run(async () => {
          const r = await releaseFirstPass(ctx.round!.id);
          return `Reviewing has started: ${r.total_seats_released} seats released.`;
        });
    }
  }
}

