/**
 * The "Emails" tab: what is waiting in the outbox, a button that sends it now, and the reminder for judges who have not
 * opened their group. Emails are queued by the database (groups released, another group available, thanks after a
 * group, invitations, reminders); nothing leaves until someone presses Send here, or a schedule calls the same
 * function (docs/email-setup.md).
 */
import { outboxSummary, remindUnopened, retryFailedEmails, sendQueuedEmails } from '../api';
import type { OutboxSummary } from '../types';
import { esc, fmtDateTime, type AdminContext, type AdminTab } from './context';

export class EmailsTab implements AdminTab {
  id = 'emails';
  label = 'Emails';

  private summary: OutboxSummary | null = null;
  /** What the last press of "Send" did, shown under the button. */
  private lastSend: { claimed: number; sent: number; failed: number } | null = null;

  async load() {
    this.summary = await outboxSummary();
  }

  render(ctx: AdminContext): string {
    const s = this.summary;
    const last = this.lastSend;
    return `
      <div class="metrics">
        <div class="metric"><b class="${s && s.due_now ? 'bad' : ''}">${s?.due_now ?? 0}</b><span>ready to send now</span></div>
        <div class="metric"><b>${s?.waiting_later ?? 0}</b><span>waiting for a later try</span></div>
        <div class="metric"><b class="${s && s.failed ? 'bad' : ''}">${s?.failed ?? 0}</b><span>given up on</span></div>
        <div class="metric"><b class="${s && s.sent_last_day ? 'good' : ''}">${s?.sent_last_day ?? 0}</b><span>sent in the last 24 hours</span></div>
      </div>
      <div class="section">
        <h3>Send the queued emails</h3>
        <p class="muted">The messages are written when something happens (the groups are released, a judge finishes a group, someone is invited) and wait here. Each press sends up to 50 of the ones that are ready. Check your provider's daily limit first: a free plan allows 100 to 300 a day.</p>
        <div class="row">
          <button type="button" class="btn btn-primary" data-action="send-emails" ${ctx.busy || !s?.due_now ? 'disabled' : ''}>Send ${s?.due_now ? `${Math.min(s.due_now, 50)} of the ${s.due_now} ` : ''}ready emails</button>
          <button type="button" class="btn btn-secondary btn-sm" data-action="refresh-emails" ${ctx.busy ? 'disabled' : ''}>Refresh</button>
        </div>
        ${last ? `<p style="margin-bottom:0;">Last press: <b>${last.sent}</b> sent${last.failed ? `, <b class="bad">${last.failed}</b> failed (they are tried again later)` : ''}.</p>` : ''}
        ${s && s.waiting_later ? `<div class="alert alert-info" style="margin-top: 1rem; margin-bottom: 0;"><b>${s.waiting_later}</b> ${s.waiting_later === 1 ? 'message is' : 'messages are'} waiting for a later try${s.next_try_at ? `, the first one from ${esc(fmtDateTime(s.next_try_at))}` : ''}.
          After a failure the wait grows (5 minutes, 30 minutes, 2 hours, 8 hours, then a day).${s.throttled ? ` ${s.throttled} failed because the provider's sending limit was reached; those are kept for up to 48 hours, so a daily limit has time to clear.` : ''}</div>` : ''}
      </div>
      ${s && s.failed ? `<div class="section">
        <h3>Messages given up on</h3>
        <p class="muted">${s.failed} ${s.failed === 1 ? 'message was' : 'messages were'} given up on (five failures, or the provider's limit for 48 hours). The usual causes are a wrong or missing email setting (docs/email-setup.md) or a daily limit that was reached. After fixing the cause, put them back in the queue.</p>
        <button type="button" class="btn btn-secondary" data-action="retry-failed" ${ctx.busy ? 'disabled' : ''}>Retry the ${s.failed} failed ${s.failed === 1 ? 'message' : 'messages'}</button>
      </div>` : ''}
      <div class="section">
        <h3>Remind judges who have not opened their group</h3>
        ${ctx.round
          ? `<p class="muted">Queues one reminder (once a day at most) for every judge of ${esc(ctx.round.name)} who has held a group for ${esc(ctx.round.reminder_after_days)} days without opening it. Reminders for one judge are on the Capacity tab (Nudge).</p>
             <button type="button" class="btn btn-secondary" data-action="remind-unopened" ${ctx.busy ? 'disabled' : ''}>Queue the reminders</button>`
          : '<p class="muted">There is no round yet.</p>'}
      </div>`;
  }

  async onAction(name: string, _el: HTMLElement, ctx: AdminContext) {
    switch (name) {
      case 'refresh-emails':
        return ctx.reload();
      case 'send-emails':
        return ctx.run(async () => {
          this.lastSend = await sendQueuedEmails(50);
          return this.lastSend.claimed ? undefined : 'Nothing was waiting.';
        });
      case 'retry-failed':
        if (!confirm('Put every failed message back in the queue? They will be ready to send at once.')) return;
        return ctx.run(async () => {
          const r = await retryFailedEmails();
          return `${r.requeued} ${r.requeued === 1 ? 'message' : 'messages'} back in the queue. Send them when your provider's limit allows.`;
        });
      case 'remind-unopened':
        return ctx.run(async () => {
          const r = await remindUnopened(ctx.round!.id);
          return r.queued ? `${r.queued} reminder${r.queued === 1 ? '' : 's'} queued. Send them with the button above.` : 'Nobody needs a reminder right now.';
        });
    }
  }
}
