/**
 * <rgai-admin>: the organizers' screen. This file is the shell: it checks that the signed-in user is an admin (the
 * database decides; the page being unlisted protects nothing), loads the event, round, review form and dashboard,
 * shows the tabs, and routes clicks to the active tab. The tabs live in ../admin/.
 */
import { BaseElement } from '../../common/base-element';
import { getSupabaseClient } from '../../common/supabase-client';
import { friendlyError, rpc } from '../api';
import { adminStyles } from '../admin/styles';
import { esc, fmtDateTime, type AdminContext, type AdminTab, type Dashboard, type Flash } from '../admin/context';
import { CapacityTab } from '../admin/capacity-tab';
import { JudgesTab } from '../admin/judges-tab';
import { EmailsTab } from '../admin/emails-tab';
import { ReportsTab } from '../admin/reports-tab';
import { ResultsTab } from '../admin/results-tab';
import { SetupTab } from '../admin/setup-tab';
import { TriggersTab } from '../admin/triggers-tab';
import type { EventItem, ReviewQuestion, Round, TriggerItem } from '../types';

export class RgaiAdminElement extends BaseElement implements AdminContext {
  events: EventItem[] = [];
  event: EventItem | null = null;
  round: Round | null = null;
  rounds: Round[] = [];
  questions: ReviewQuestion[] = [];
  triggers: TriggerItem[] = [];
  dashboard: Dashboard | null = null;
  testClock: string | null = null;
  draftTrigger: { label: string; description: string } | null = null;
  busy = false;

  private isAdmin = false;
  private loading = true;
  private loadError: string | null = null;
  private message: Flash | null = null;
  private tabs: AdminTab[] = [new SetupTab(), new JudgesTab(), new CapacityTab(), new ReportsTab(), new TriggersTab(), new ResultsTab(), new EmailsTab()];
  private active = 'setup';
  /** The round number the admin is looking at; null = the latest round of the event. */
  private roundNumber: number | null = null;
  private roundEventId: string | null = null;

  constructor() {
    super(adminStyles);
    // One listener for the whole screen; elements say what they do with data-action.
    this.root.addEventListener('click', (e) => void this.dispatch(e));
    this.root.addEventListener('change', (e) => {
      const el = (e.target as HTMLElement).closest<HTMLElement>('select[data-action], input[data-action]');
      if (el) void this.dispatch(e, el);
    });
  }

  connectedCallback() {
    void this.start();
  }

  // ── AdminContext ─────────────────────────────────────────────────────────────────────────────
  flash(type: Flash['type'], text: string) {
    this.message = { type, text };
    this.render();
  }

  async run(fn: () => Promise<string | void>) {
    this.busy = true;
    this.message = null;
    this.render();
    try {
      const ok = await fn();
      if (ok) this.message = { type: 'success', text: ok };
      await this.reload();
    } catch (err) {
      this.message = { type: 'error', text: friendlyError(err) };
      this.busy = false;
      this.render();
      return;
    }
    this.busy = false;
    this.render();
  }

  async reload() {
    await this.loadData();
    const tab = this.tabs.find((t) => t.id === this.active);
    try {
      await tab?.load?.(this);
    } catch (err) {
      this.message = { type: 'error', text: friendlyError(err) };
    }
    this.render();
  }

  rerender() {
    this.render();
  }

  selectRound(number: number) {
    this.roundNumber = number;
  }

  go(tab: string) {
    this.active = tab;
    this.message = null;
    void this.reload();
  }

  // ── loading ──────────────────────────────────────────────────────────────────────────────────
  private async start() {
    this.loading = true;
    this.render();
    try {
      this.isAdmin = Boolean(await rpc<boolean>('is_admin'));
      if (this.isAdmin) await this.loadData(true);
      if (this.isAdmin) await this.tabs.find((t) => t.id === this.active)?.load?.(this);
    } catch (err) {
      this.isAdmin = false;
      this.loadError = friendlyError(err, 'The admin screen could not be loaded.');
    } finally {
      this.loading = false;
      this.render();
    }
  }

  private async loadData(first = false) {
    const sb = getSupabaseClient();
    this.testClock = (await rpc<{ override: string | null }>('admin_get_test_clock'))?.override ?? null;
    const t = await sb.from('triggers').select('*').order('position').order('label');
    if (t.error) throw t.error;
    this.triggers = t.data ?? [];
    const ev = await sb.from('events').select('*').order('created_at', { ascending: false });
    if (ev.error) throw ev.error;
    this.events = ev.data ?? [];
    const keep = this.event && this.events.find((e) => e.id === this.event!.id);
    this.event = keep ?? (first ? this.events.find((e) => e.status === 'open') : undefined) ?? this.events[0] ?? null;
    this.round = null;
    this.rounds = [];
    this.questions = [];
    this.dashboard = null;
    if (this.event) {
      const rs = await sb.from('rounds').select('*').eq('event_id', this.event.id).order('number');
      if (rs.error) throw rs.error;
      this.rounds = rs.data ?? [];
      // another event starts at its latest round; the same event keeps the round that was chosen
      if (this.roundEventId !== this.event.id) this.roundNumber = null;
      this.roundEventId = this.event.id;
      this.round = this.rounds.find((r) => r.number === this.roundNumber) ?? this.rounds[this.rounds.length - 1] ?? null;
      this.roundNumber = this.round?.number ?? null;
      if (this.round) {
        const q = await sb.from('review_questions').select('*').eq('round_id', this.round.id).order('position');
        if (q.error) throw q.error;
        this.questions = q.data ?? [];
        this.dashboard = await rpc<Dashboard>('get_admin_dashboard_stats', { p_round_id: this.round.id });
        this.round = this.dashboard.round ?? this.round;
      }
    }
  }

  // ── events ───────────────────────────────────────────────────────────────────────────────────
  private async dispatch(e: Event, forced?: HTMLElement) {
    const el = forced ?? (e.target as HTMLElement).closest<HTMLElement>('[data-action]');
    // selects and checkboxes act on "change", not on the click that precedes it
    if (!el || (e.type === 'click' && (el.tagName === 'SELECT' || el.tagName === 'INPUT'))) return;
    const name = el.getAttribute('data-action') ?? '';
    if (name === 'tab') return this.go(el.getAttribute('data-tab') ?? 'setup');
    if (name === 'round') {
      this.selectRound(Number(el.getAttribute('data-round')));
      this.message = null;
      return void (await this.reload());
    }
    if (name === 'dismiss') {
      this.message = null;
      return this.render();
    }
    try {
      await this.tabs.find((t) => t.id === this.active)?.onAction?.(name, el, this, this.root);
    } catch (err) {
      this.flash('error', friendlyError(err));
    }
  }

  // ── rendering ────────────────────────────────────────────────────────────────────────────────
  private render() {
    if (this.loading) {
      this.root.innerHTML = '<div class="admin-card"><div class="empty">Loading the admin screen…</div></div>';
      return;
    }
    if (this.loadError) {
      this.root.innerHTML = `<div class="admin-card"><div class="alert alert-error"><b>The admin screen could not be loaded.</b> ${esc(this.loadError)}</div></div>`;
      return;
    }
    if (!this.isAdmin) {
      this.root.innerHTML = `<div class="admin-card" style="text-align:center; padding: 3rem;"><h2 style="color:#991b1b; margin-top:0;">Access denied</h2><p class="muted">This screen is for the organizers. To switch to an administrator account, sign out with the account button at the top of the page.</p></div>`;
      return;
    }
    // keep scroll position and focus-free inputs across re-renders
    const tab = this.tabs.find((t) => t.id === this.active) ?? this.tabs[0];
    const y = window.scrollY;
    this.root.innerHTML = `
      <div class="admin-card">
        ${this.testClock ? `<div class="alert alert-error clock-banner" role="alert"><b>Test clock is set to ${esc(fmtDateTime(this.testClock))}:</b> every story-review rule runs as if it were then.</div>` : ''}
        <div class="header">
          <div><h1 class="title">Story review: organizers</h1>
            <p class="subtitle">${esc(this.event?.title ?? 'No event yet')}${this.round ? ` · round ${esc(this.round.number)} is ${esc(this.round.status)}` : ''}</p></div>
          <div class="row"><span class="badge badge-admin">Admin</span></div>
        </div>
        ${this.rounds.length > 1 ? `<div class="tabs round-switch" role="group" aria-label="Round">${this.rounds.map((r) => `<button type="button" class="tab-btn ${r.number === this.round?.number ? 'active' : ''}" data-action="round" data-round="${esc(r.number)}" aria-pressed="${r.number === this.round?.number}">${esc(r.name)}</button>`).join('')}</div>` : ''}
        <div class="tabs">${this.tabs.map((t) => `<button type="button" class="tab-btn ${t.id === tab.id ? 'active' : ''}" data-action="tab" data-tab="${esc(t.id)}">${esc(t.label)}</button>`).join('')}</div>
        ${this.message ? `<div class="alert alert-${this.message.type}">${esc(this.message.text)} <button type="button" class="btn btn-sm btn-secondary" data-action="dismiss" style="float:right;">OK</button></div>` : ''}
        ${tab.render(this)}
      </div>`;
    window.scrollTo({ top: y });
  }
}

if (!customElements.get('rgai-admin')) {
  customElements.define('rgai-admin', RgaiAdminElement);
}
