/**
 * The "Trigger reports" tab: stories that a judge skipped as "has a warning the author did not declare" or "does not
 * have the warning they declared". Confirm changes the story's warnings (adds or removes the themes the judge named)
 * and refreshes the group; dismiss leaves the story alone. After a confirm, judges who now hold a group with a theme
 * they blocked are listed, with a button to release their seat.
 */
import { adminJudges, releaseSeat, reviewTriggerReport } from '../api';
import type { AdminJudge } from '../types';
import { esc, triggerTags, type AdminContext, type AdminTab } from './context';

const REASONS: Record<string, string> = {
  undeclared_trigger: 'has a warning that was not declared',
  misdeclared_trigger: 'does not have a warning that was declared',
};

export class ReportsTab implements AdminTab {
  id = 'reports';
  label = 'Trigger reports';

  private judges: AdminJudge[] = [];
  private toReview: { story: string; seats: { seat_id: string; judge_id: string }[] } | null = null;

  async load(ctx: AdminContext) {
    this.judges = ctx.round ? await adminJudges(ctx.round.id) : [];
  }

  render(ctx: AdminContext): string {
    const queue = ctx.dashboard?.trigger_queue ?? [];
    return `
      ${this.toReview ? this.toReviewHtml(ctx) : ''}
      <div class="section"><h3>Reports waiting for you (${queue.length})</h3>
        ${queue.length === 0 ? '<div class="empty">No open trigger reports.</div>' : `<div class="table-wrap"><table><thead><tr><th>Story</th><th>The judge says it…</th><th>Themes</th><th>Note</th><th></th></tr></thead><tbody>
          ${queue.map((r) => `<tr><td><b>${esc(r.story_title)}</b></td><td>${esc(REASONS[r.skip_reason] ?? r.skip_reason)}</td><td>${triggerTags(r.flagged_triggers ?? [], ctx.triggers)}</td><td>${esc(r.skip_note ?? '')}</td>
            <td><div class="row"><button type="button" class="btn btn-success btn-sm" data-action="confirm-report" data-id="${esc(r.assignment_id)}" data-story="${esc(r.story_title)}" ${ctx.busy || !(r.flagged_triggers ?? []).length ? 'disabled' : ''}>Confirm</button>
            <button type="button" class="btn btn-secondary btn-sm" data-action="dismiss-report" data-id="${esc(r.assignment_id)}" ${ctx.busy ? 'disabled' : ''}>Dismiss</button>
            <button type="button" class="btn btn-secondary btn-sm" data-action="new-trigger-from-report" data-note="${esc(r.skip_note ?? '')}" title="The list has no theme for this: add one, filled in from the note">Add as a new trigger</button></div></td></tr>`).join('')}
        </tbody></table></div>`}
        <p class="muted">Confirm: the story's content warnings change as the judge says and its group's warnings follow. Dismiss: nothing changes. Either way the report leaves this list.</p>
      </div>`;
  }

  private toReviewHtml(ctx: AdminContext): string {
    const t = this.toReview!;
    if (!t.seats.length) return `<div class="alert alert-success">Confirmed for “${esc(t.story)}”. No judge holding that group blocked the new theme.</div>`;
    return `<div class="alert alert-warning"><b>Confirmed for “${esc(t.story)}”.</b> These judges hold the group and blocked one of its themes. Release their seat so another judge can take it:
      <ul>${t.seats.map((s) => `<li>${esc(this.judges.find((j) => j.user_id === s.judge_id)?.display_name ?? s.judge_id)}
        <button type="button" class="btn btn-danger btn-sm" data-action="release-seat" data-seat="${esc(s.seat_id)}" ${ctx.busy ? 'disabled' : ''}>Release seat</button></li>`).join('')}</ul></div>`;
  }

  async onAction(name: string, el: HTMLElement, ctx: AdminContext) {
    const id = el.getAttribute('data-id') ?? '';
    switch (name) {
      case 'confirm-report':
        return ctx.run(async () => {
          const r = await reviewTriggerReport(id, 'confirm');
          this.toReview = { story: el.getAttribute('data-story') ?? '', seats: r.seats_to_review ?? [] };
        });
      case 'new-trigger-from-report': {
        // pre-fill the add form of the Triggers tab from the judge's note: the label is its first 80 characters, the description all of it (up to 300)
        const note = (el.getAttribute('data-note') ?? '').trim();
        ctx.draftTrigger = { label: note.slice(0, 80), description: note.slice(0, 300) };
        return ctx.go('triggers');
      }
      case 'dismiss-report':
        return ctx.run(async () => {
          await reviewTriggerReport(id, 'dismiss');
          this.toReview = null;
          return 'Report dismissed.';
        });
      case 'release-seat':
        return ctx.run(async () => {
          await releaseSeat(el.getAttribute('data-seat') ?? '', 'trigger confirmed');
          if (this.toReview) this.toReview.seats = this.toReview.seats.filter((s) => s.seat_id !== el.getAttribute('data-seat'));
          return 'Seat released.';
        });
    }
  }
}
