export class RgaiAccountElement extends BaseElement {
  private profile: Profile | null = null;
  private triggers: TriggerItem[] = [];
  private loading = true;

  constructor() {
    super(styles);
  }

  async connectedCallback() {
    await this.loadData();
  }

  private async loadData() {
    const supabase = getSupabaseClient();
    this.loading = true;
    this.render();

    try {
      const { data: authData } = await supabase.auth.getUser();
      if (!authData.user) {
        this.emit('rgai-unauthenticated');
        return;
      }

      // Fetch profile
      const { data: prof, error: profErr } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', authData.user.id)
        .single();

      if (profErr) throw profErr;
      this.profile = prof;

      // The whole list: the view hides the retired triggers the person has not selected
      const { data: trigList, error: trigErr } = await supabase
        .from('triggers')
        .select('*')
        .order('position')
        .order('label');

      if (!trigErr && trigList) {
        this.triggers = trigList;
      }
    } catch (err) {
      console.error('Failed to load profile:', err);
    } finally {
      this.loading = false;
      this.render();
    }
  }

  private render() {
    if (this.loading) {
      this.root.innerHTML = `<div class="account-card"><p>Loading profile...</p></div>`;
      return;
    }

    if (!this.profile) {
      this.root.innerHTML = `
        <div class="account-card" style="text-align: center; padding: 2.5rem 1rem;">
          <h2 class="title" style="margin-bottom: 0.5rem; font-size: 1.3rem;">Not Signed In or Session Expired</h2>
          <p style="color: #64748b; margin-bottom: 1.5rem; max-width: 420px; margin-left: auto; margin-right: auto;">
            We couldn't load your account profile. Your session may have expired or been reset. Try again, or sign out
            and back in with the account button at the top of the page.
          </p>
          <button type="button" class="btn-save" id="btn-retry-profile" style="padding: 0.65rem 1.5rem; cursor: pointer;">
            Try again
          </button>
        </div>
      `;
      this.$('#btn-retry-profile')?.addEventListener('click', () => void this.loadData());
      return;
    }

    this.root.innerHTML = accountHtml(this.profile, this.triggers);

    this.bindEvents();
  }

  private bindEvents() {
    this.$('#account-form')?.addEventListener('submit', async (e) => {
      e.preventDefault();
      await this.saveProfile();
    });
  }

  private async saveProfile() {
    if (!this.profile) return;
    const displayName = (this.$<HTMLInputElement>('#display-name')?.value || '').trim();
    const emailDigest = this.$<HTMLInputElement>('#email-digest')?.checked ?? true;
    const newsletterOptIn = this.$<HTMLInputElement>('#newsletter-opt-in')?.checked ?? false;

    const checkedTriggers: string[] = [];
    this.$$<HTMLInputElement>('input[name="trigger"]:checked').forEach((cb) => {
      checkedTriggers.push(cb.value);
    });

    const msgEl = this.$('#status-msg');
    try {
      const supabase = getSupabaseClient();
      const { error } = await supabase
        .from('profiles')
        .update({
          display_name: displayName,
          default_blocked_triggers: checkedTriggers,
          email_digest: emailDigest,
          newsletter_opt_in: newsletterOptIn,
        })
        .eq('id', this.profile.id);

      if (error) throw error;

      this.profile.display_name = displayName;
      this.profile.default_blocked_triggers = checkedTriggers;
      this.profile.email_digest = emailDigest;
      this.profile.newsletter_opt_in = newsletterOptIn;

      if (msgEl) {
        msgEl.textContent = 'Profile updated successfully!';
        msgEl.className = 'msg success';
      }
    } catch (err: unknown) {
      if (msgEl) {
        msgEl.textContent = err instanceof Error ? err.message : String(err);
        msgEl.className = 'msg error';
      }
    }
  }
}

if (!customElements.get('rgai-account')) {
  customElements.define('rgai-account', RgaiAccountElement);
}
